import spidev
import time
import signal
import sys
import logging

# Set up logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class LoadCellReader:
    def __init__(self, spi_bus=0, spi_device=0, max_speed_hz=50000, mode=0b00, bits_per_word=8):
        self.spi_bus = spi_bus
        self.spi_device = spi_device
        self.max_speed_hz = max_speed_hz
        self.mode = mode
        self.bits_per_word = bits_per_word
        self.spi = None
        self.opened = False

    def __enter__(self):
        self.open()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close()

    def open(self):
        try:
            self.spi = spidev.SpiDev()
            self.spi.open(self.spi_bus, self.spi_device)
            self.spi.max_speed_hz = self.max_speed_hz
            self.spi.mode = self.mode
            self.spi.bits_per_word = self.bits_per_word
            self.opened = True
            logging.info("SPI device opened successfully.")
        except OSError as e:
            logging.error(f"Failed to open SPI device: {e}")
            self.opened = False
            raise

    def close(self):
        if self.opened:
            try:
                self.spi.close()
                logging.info("SPI device closed.")
            except Exception as e:
                logging.error(f"Error closing SPI device: {e}")
            finally:
                self.opened = False

    def send_spi_command(self, data):
        if not self.opened:
            raise RuntimeError("SPI device not opened.")
        try:
            response = self.spi.xfer2(data)
            logging.debug(f"SPI command sent, response: {response}")
            return response
        except OSError as e:
            logging.error(f"SPI xfer2 failed: {e}")
            raise

    def extract_10bit(self, response):
        if len(response) < 3:
            raise ValueError("Response must be at least 3 bytes long.")
        return ((response[1] & 0x03) << 8) | response[2]

    def read_raw_data(self):
        if not self.opened:
            raise RuntimeError("SPI device not opened.")
        try:
            data = [0x01, 0x80, 0x00]
            response = self.send_spi_command(data)
            raw_data = self.extract_10bit(response)
            logging.debug(f"Raw 10-bit data: {raw_data}")
            return raw_data
        except Exception as e:
            logging.error(f"Error reading raw data: {e}")
            raise

    def convert_to_weight(self, raw_data):
        if not isinstance(raw_data, int) or raw_data < 0 or raw_data > 1023:
            raise ValueError("Invalid raw data for weight conversion.")
        weight = float(raw_data) * (5.0 / 1023.0)
        return weight

    def read_weight(self):
        try:
            raw_data = self.read_raw_data()
            weight = self.convert_to_weight(raw_data)
            return weight
        except Exception as e:
            logging.error(f"Error reading weight: {e}")
            return None

def main():
    try:
        with LoadCellReader() as reader:
            while True:
                weight = reader.read_weight()
                if weight is not None:
                    print(f"Weight: {weight:.2f} kg")
                time.sleep(0.5)
    except KeyboardInterrupt:
        logging.info("Interrupted by user.")
    except Exception as e:
        logging.error(f"Main loop error: {e}")
    finally:
        print("Shutting down LoadCellReader.")

def signal_handler(sig, frame):
    logging.info("Received signal to terminate.")
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGTERM, signal_handler)
    main()

