import signal
import time
import pigpio
import board
import busio
import adafruit_lsm303
import adafruit_ads1x15.ads1015 as ADS
from adafruit_ads1x15.analog_in import AnalogIn
import logging

# Setup logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class MotorController:
    def __init__(self, dir_pin, step_pin, ms0_pin, ms1_pin):
        self.pi = pigpio.pi()
        if not self.pi.connected:
            raise RuntimeError("Failed to connect to pigpio daemon")
        self.dir_pin = dir_pin
        self.step_pin = step_pin
        self.ms0_pin = ms0_pin
        self.ms1_pin = ms1_pin
        self.pi.set_mode(self.dir_pin, pigpio.OUTPUT)
        self.pi.set_mode(self.step_pin, pigpio.OUTPUT)
        self.pi.set_mode(self.ms0_pin, pigpio.OUTPUT)
        self.pi.set_mode(self.ms1_pin, pigpio.OUTPUT)
        self.set_microstep_resolution("Full")
        self.set_direction("CCW")
        self.pwm_duty_cycle = 0
        self.pwm_frequency = 500
        self.pwm_timer = self.pi.set_PWM_dutycycle(self.step_pin, self.pwm_duty_cycle)

    def set_microstep_resolution(self, resolution):
        if resolution == "Full":
            self.pi.write(self.ms0_pin, 0)
            self.pi.write(self.ms1_pin, 0)
        elif resolution == "Half":
            self.pi.write(self.ms0_pin, 1)
            self.pi.write(self.ms1_pin, 0)
        elif resolution == "Quarter":
            self.pi.write(self.ms0_pin, 0)
            self.pi.write(self.ms1_pin, 1)
        elif resolution == "Eighth":
            self.pi.write(self.ms0_pin, 1)
            self.pi.write(self.ms1_pin, 1)
        else:
            raise ValueError("Invalid microstep resolution")

    def set_direction(self, direction):
        if direction == "CCW":
            self.pi.write(self.dir_pin, 0)
        elif direction == "CW":
            self.pi.write(self.dir_pin, 1)
        else:
            raise ValueError("Invalid direction")

    def set_pwm_duty_cycle(self, duty_cycle):
        if 0 <= duty_cycle <= 255:
            self.pwm_duty_cycle = duty_cycle
            self.pi.set_PWM_dutycycle(self.step_pin, self.pwm_duty_cycle)
        else:
            raise ValueError("Duty cycle must be between 0 and 255")

    def cleanup(self):
        self.pi.set_PWM_dutycycle(self.step_pin, 0)
        self.pi.stop()


class SensorManager:
    def __init__(self, i2c_bus):
        try:
            self.i2c = busio.I2C(board.SCL, board.SDA)
            self.accel = adafruit_lsm303.LSM303_Accel_I2C(self.i2c)
            self.mag = adafruit_lsm303.LSM303_Mag_I2C(self.i2c)
        except Exception as e:
            logging.error(f"Failed to initialize sensors: {e}")
            raise

    def read_acceleration(self):
        try:
            x, y, z = self.accel.acceleration
            return x, y, z
        except Exception as e:
            logging.error(f"Error reading acceleration: {e}")
            return None, None, None

    def read_magnetic_field(self):
        try:
            x, y, z = self.mag.magnetic
            return x, y, z
        except Exception as e:
            logging.error(f"Error reading magnetic field: {e}")
            return None, None, None

    def read_heading(self):
        try:
            x, y = self.mag.magnetic
            heading_rad = math.atan2(y, x)
            heading_deg = math.degrees(heading_rad)
            if heading_deg < 0:
                heading_deg += 360
            return heading_deg
        except Exception as e:
            logging.error(f"Error calculating heading: {e}")
            return None

    def read_inclination(self):
        try:
            x, y, z = self.accel.acceleration
            inclination_xz = math.degrees(math.atan2(x, z))
            inclination_yz = math.degrees(math.atan2(y, z))
            return inclination_xz, inclination_yz
        except Exception as e:
            logging.error(f"Error reading inclination: {e}")
            return None, None


class ADCManager:
    def __init__(self, i2c_bus, address=0x48, gain=1):
        try:
            self.i2c = i2c_bus
            self.ads = ADS.ADS1015(self.i2c, address=address)
            self.channel = AnalogIn(self.ads, ADS.P0)
            self.gain = gain
        except Exception as e:
            logging.error(f"Failed to initialize ADC: {e}")
            raise

    def read_voltage(self):
        try:
            voltage = self.channel.voltage
            return voltage
        except Exception as e:
            logging.error(f"Error reading ADC voltage: {e}")
            return None


def signal_handler(sig, frame):
    logging.info("Shutting down gracefully...")
    motor.cleanup()
    sys.exit(0)


if __name__ == "__main__":
    import math
    import sys

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        motor = MotorController(dir_pin=20, step_pin=21, ms0_pin=14, ms1_pin=15)
        i2c = busio.I2C(board.SCL, board.SDA)
        sensor = SensorManager(i2c)
        adc = ADCManager(i2c)

        while True:
            try:
                adc_voltage = adc.read_voltage()
                if adc_voltage is not None:
                    duty_cycle = int((adc_voltage / 3.3) * 255)
                    motor.set_pwm_duty_cycle(duty_cycle)
                    logging.info(f"ADC Voltage: {adc_voltage:.4f}V -> Duty Cycle: {duty_cycle}")

                acc_x, acc_y, acc_z = sensor.read_acceleration()
                mag_x, mag_y, mag_z = sensor.read_magnetic_field()
                heading = sensor.read_heading()
                incl_xz, incl_yz = sensor.read_inclination()

                if acc_x is not None and acc_y is not None and acc_z is not None:
                    logging.info(f"Acceleration (m/s²): X={acc_x:.4f}, Y={acc_y:.4f}, Z={acc_z:.4f}")
                if mag_x is not None and mag_y is not None and mag_z is not None:
                    logging.info(f"Magnetic Field (G): X={mag_x:.4f}, Y={mag_y:.4f}, Z={mag_z:.4f}")
                if heading is not None:
                    logging.info(f"Heading (°): {heading:.2f}")
                if incl_xz is not None and incl_yz is not None:
                    logging.info(f"Inclination: XZ={incl_xz:.2f}°, YZ={incl_yz:.2f}°")

                time.sleep(1)

            except Exception as e:
                logging.error(f"Error in main loop: {e}")
                time.sleep(1)

    except Exception as e:
        logging.error(f"Initialization error: {e}")
        sys.exit(1)
    finally:
        motor.cleanup()

