import os
import time
import logging
import signal
import spidev
from gpiozero import LED, Relay
from adafruit_dht import DHT22
from datetime import datetime
import json

# Configuration
LOG_FILE = 'greenhouse.log'
SENSOR_PIN = 4  # BCM
PUMP_PIN = 17
FAN_PIN = 27
LIGHT_PIN = 22
LED_PIN = 25
ADC_CS_PIN = 8
ADC_CHANNEL = 0
WATCHDOG_TIMEOUT = 600  # seconds
SENSOR_INTERVAL = 300  # seconds
LED_BLINK_INTERVAL = 0.2
LED_BLINK_COUNT = 5

# Initialize logging
logging.basicConfig(filename=LOG_FILE, level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Initialize GPIO and SPI
try:
    # Initialize GPIO
    pump = Relay(PUMP_PIN)
    fan = Relay(FAN_PIN)
    light = Relay(LIGHT_PIN)
    status_led = LED(LED_PIN)

    # Initialize SPI
    spi = spidev.SpiDev()
    spi.open(0, 0)  # bus 0, device 0 (CE0)
    spi.max_speed_hz = 1000000  # 1 MHz
    spi.mode = 0b00  # CPOL=0, CPHA=0
except Exception as e:
    logging.error(f"Initialization error: {e}")
    exit(1)

# DHT22 setup
try:
    dht_sensor = DHT22(SENSOR_PIN)
except Exception as e:
    logging.warning(f"DHT22 sensor not found or not connected: {e}")
    dht_sensor = None

def control_pump(command):
    try:
        if command == 'on':
            pump.on()
        elif command == 'off':
            pump.off()
        else:
            logging.warning(f"Invalid pump command: {command}")
    except Exception as e:
        logging.error(f"Error controlling pump: {e}")

def control_fan(command):
    try:
        if command == 'on':
            fan.on()
        elif command == 'off':
            fan.off()
        else:
            logging.warning(f"Invalid fan command: {command}")
    except Exception as e:
        logging.error(f"Error controlling fan: {e}")

def control_light(command):
    try:
        if command == 'on':
            light.on()
        elif command == 'off':
            light.off()
        else:
            logging.warning(f"Invalid light command: {command}")
    except Exception as e:
        logging.error(f"Error controlling light: {e}")

def set_led_status(status):
    try:
        if status == 'online':
            status_led.on()
        elif status == 'offline':
            status_led.off()
        elif status == 'error' or status == 'synchronizing':
            for _ in range(LED_BLINK_COUNT):
                status_led.on()
                time.sleep(LED_BLINK_INTERVAL)
                status_led.off()
                time.sleep(LED_BLINK_INTERVAL)
        else:
            logging.warning(f"Invalid LED status: {status}")
    except Exception as e:
        logging.error(f"Error setting LED status: {e}")

def read_adc(channel):
    try:
        # Read ADC value
        adc = spi.xfer2([1, (8 + channel) << 4, 0])
        data = ((adc[1] & 0b11110000) >> 4) | (adc[2] & 0b1111)
        return data
    except Exception as e:
        logging.error(f"ADC read error: {e}")
        return None

def read_sensor_data():
    try:
        if dht_sensor is None:
            logging.warning("DHT22 sensor not available, skipping read.")
            return None
        humidity, temperature = dht_sensor.humidity, dht_sensor.temperature
        return {
            'timestamp': datetime.now().isoformat(),
            'temperature': temperature,
            'humidity': humidity
        }
    except Exception as e:
        logging.error(f"Sensor read error: {e}")
        return None

def watchdog():
    last_read = time.time()
    last_command = time.time()
