import argparse
import RPi.GPIO as GPIO
import spidev
import sys

# Setup logging
logging.basicConfig(filename='sound_sensor.log', level=logging.ERROR, format='%(asctime)s - %(levelname)s - %(message)s')

class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins=None, channels=None, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.log_queue = log_queue
        self.running = True
        self.last_event_time = 0

        if sensor_type == 'digital':
            if not gpio_pins:
                raise ValueError("gpio_pins must be provided for digital sensors")
            self.gpio_pins = gpio_pins
            self.setup_gpio()
        elif sensor_type == 'analog':
            if not channels:
                raise ValueError("channels must be provided for analog sensors")
            self.channels = channels
            self.spi = self.setup_spi(spi_speed)
        else:
            raise ValueError("Invalid sensor type. Use 'digital' or 'analog'")

    def setup_gpio(self):
        try:
            GPIO.setmode(GPIO.BCM)
            for pin in self.gpio_pins:
                GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        except Exception as e:
            logging.error(f"GPIO setup failed for sensor {self.sensor_id}: {e}")
            raise

    def setup_spi(self, spi_speed):
        try:
            spi = spidev.SpiDev()
            spi.open(0, 0)
            spi.max_speed_hz = spi_speed
            return spi
        except Exception as e:
            logging.error(f"SPI setup failed for sensor {self.sensor_id}: {e}")
            raise

    def read_analog(self):
        try:
            # SPI command: start bit (0b1), single-ended (0b0), channel (0b000), dummy byte (0x00)
            # 10-bit result is in the first two bytes
            data = self.spi.xfer([0b10000000, 0b00000000] + [0x00] * 3)
            result = (data[1] << 8) | data[2]
            return result
        except Exception as e:
            logging.error(f"SPI read failed for sensor {self.sensor_id}: {e}")
            return None

    def read_digital(self):
        for pin in self.gpio_pins:
            try:
                return GPIO.input(pin)
            except Exception as e:
                logging.error(f"GPIO read failed for sensor {self.sensor_id} pin {pin}: {e}")
                return None
        return None

    def detect_event(self):
        if self.sensor_type == 'digital':
            value = self.read_digital()
            if value is not None and value == 1:
                return True
        elif self.sensor_type == 'analog':
            value = self.read_analog()
            if value is not None and value >= self.threshold:
                return True
        return False

    def run(self):
        try:
            while self.running:
                if self.detect_event():
                    if time.time() - self.last_event_time > 0.1:
                        self.last_event_time = time.time()
                        event = {
                            'sensor_id': self.sensor_id,
                            'timestamp': time.time(),
                            'type': self.sensor_type,
                            'value': self.read_digital() if self.sensor_type == 'digital' else self.read_analog()
                        }
                        self.log_queue.put(event)
                time.sleep(1.0 / self.sample_rate)
        except KeyboardInterrupt:
            logging.info(f"Sensor {self.sensor_id} interrupted")
        except Exception as e:
            logging.error(f"Sensor {self.sensor_id} error: {e}")
        finally:
            if self.sensor_type == 'digital':
                GPIO.cleanup(self.gpio_pins)
            elif self.sensor_type == 'analog':
                self.spi.close()

    def stop(self):
        self.running = False

def main():
    parser = argparse.ArgumentParser(description="Sound Sensor Monitor for Raspberry Pi")
    parser.add_argument('--sensor_type', required=True, choices=['digital', 'analog'], help="Sensor type: digital or analog")
    parser.add_argument('--threshold', type=int, default=500, help="Threshold for analog sensors")
    parser.add_argument('--sample_rate', type=int, default=10, help="Sample rate in Hz")
    parser.add_argument('--log_file', default='sound_events.log', help="Log file for events")
    parser.add_argument('--gpio_pins', nargs='+', type=int, help="GPIO pins for digital sensors")
    parser.add_argument('--channels', nargs='+', type=int, help="ADC channels for analog sensors")
    parser.add_argument('--spi_speed', type=int, default=1000000, help="SPI speed in Hz")
    parser.add_argument('--sensor_ids', nargs='+', required=True, help="List of sensor IDs")

    args = parser.parse_args()

    log_queue = queue.Queue()

    sensors = []
    for sensor_id in args.sensor_ids:
        if args.sensor_type == 'digital':
            if not args.gpio_pins:
                print("Error: --gpio_pins is required for digital sensors")
                sys.exit(1)
            sensor = SoundSensor(sensor_id, args.sensor_type, args.threshold, args.sample_rate, args.gpio_pins, None, args.spi_speed, log_queue)
        else:  # analog
            if not args.channels:
                print("Error: --channels is required for analog sensors")
                sys.exit(1)
            sensor = SoundSensor(sensor_id, args.sensor_type, args.threshold, args.sample_rate, None, args.channels, args.spi_speed, log_queue)
        sensors.append(sensor)

    try:
        threads = []
        for sensor in sensors:
            t = threading.Thread(target=sensor.run, daemon=True)
            t.start()
            threads.append(t)

        # Wait for keyboard interrupt
        try:
            while True:
                time.sleep(1)
        except KeyboardInterrupt:
            logging.info("Received keyboard interrupt, shutting down...")
            for sensor in sensors:
                sensor.stop()
            for t in threads:
                t.join()
    except Exception as e:
        logging.error(f"Main error: {e}")
    finally:
        for sensor in sensors:
            if sensor.sensor_type == 'digital':
                GPIO.cleanup(sensor.gpio_pins)
            elif sensor.sensor_type == 'analog':
                sensor.spi.close()

if __name__ == "__main__":
    main()

