import time
import signal
import logging
import smbus2
from threading import Lock

# Configuration
ADS1115_I2C_ADDR = 0x48
ADS1115_BUS = 3
ADS1115_CONFIG = 0x83E0  # Single-shot, AIN0/GND, +/-6.144V
AIN0_REGISTER = 0x00
R1 = 2000
R2 = 1000
C = 0.99
V_MIN = 10.5
V_MAX = 13.8
UPDATE_INTERVAL = 1.0
CHECK_DELTA = 1.0
LOG_FORMAT = "%(asctime)s - %(levelname)s - %(message)s"

# Initialize logging
logging.basicConfig(level=logging.WARNING, format=LOG_FORMAT)

# Global variables
last_printed_charge = 0.0
last_printed_voltage = 0.0
i2c_bus = None
lock = Lock()

def configure_ads1115(bus):
    try:
        bus.write_i2c_block_data(ADS1115_I2C_ADDR, 0x2F, [(ADS1115_CONFIG >> 8) & 0xFF, ADS1115_CONFIG & 0xFF])
        time.sleep(0.1)
    except Exception as e:
        logging.warning(f"Failed to configure ADS1115: {e}")
        raise

def read_ads1115(bus):
    try:
        data = bus.read_i2c_block_data(ADS1115_I2C_ADDR, AIN0_REGISTER, 2)
        raw = (data[0] << 8) | data[1]
        if raw & 0x8000:
            raw -= 0x10000
        return raw
    except Exception as e:
        logging.warning(f"Failed to read ADS1115: {e}")
        return None

def calculate_voltage(raw):
    if raw is None:
        return None
    v = (raw / 32767.0) * 6.144 * (R1 + R2) / R2 * C
    return v

def calculate_charge(v):
    if v is None:
        return None
    if v < V_MIN:
        return 0.0
    elif v > V_MAX:
        return 100.0
    else:
        return ((v - V_MIN) / (V_MAX - V_MIN)) * 100.0

def print_battery_status(v, p):
    print(f"Battery Voltage: {v:.2f} V | Charge: {p:.2f}%")

def signal_handler(sig, frame):
    logging.info("Shutting down gracefully...")
    if i2c_bus:
        try:
            i2c_bus.close()
        except Exception as e:
            logging.error(f"Error closing I2C bus: {e}")
    exit(0)

def main():
    global i2c_bus, last_printed_charge, last_printed_voltage

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        i2c_bus = smbus2.SMBus(ADS1115_BUS)
    except Exception as e:
        logging.error(f"Failed to open I2C bus {ADS1115_BUS}: {e}")
        return

    try:
        configure_ads1115(i2c_bus)
    except Exception as e:
        logging.error(f"ADS1115 configuration failed: {e}")
        return

    while True:
        try:
            with lock:
                raw = read_ads1115(i2c_bus)
                if raw is None:
                    logging.warning("ADS1115 read failed, retrying...")
                    time.sleep(1)
                    continue

                v = calculate_voltage(raw)
                p = calculate_charge(v)

                if v is not None and p is not None:
                    if abs(p - last_printed_charge) >= CHECK_DELTA:
                        print_battery_status(v, p)
                        last_printed_voltage = v
                        last_printed_charge = p

        except Exception as e:
            logging.error(f"Unexpected error: {e}")
            time.sleep(1)

        time.sleep(UPDATE_INTERVAL)

if __name__ == "__main__":
    main()

