    if v is None:
        return None
    if v < V_MIN:
        return 0.0
    elif v > V_MAX:
        return 100.0
    else:
        return ((v - V_MIN) / (V_MAX - V_MIN)) * 100.0

def print_battery_status(v, p):
    print(f"Battery Voltage: {v:.2f} V | Charge: {p:.2f}%")

def signal_handler(sig, frame):
    logging.info("Shutting down gracefully...")
    if i2c_bus:
        try:
            i2c_bus.close()
        except Exception as e:
            logging.error(f"Error closing I2C bus: {e}")
    exit(0)

def main():
    global i2c_bus, last_printed_charge, last_printed_voltage

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        i2c_bus = smbus2.SMBus(ADS1115_BUS)
    except Exception as e:
        logging.error(f"Failed to open I2C bus {ADS1115_BUS}: {e}")
        return

    try:
        configure_ads1115(i2c_bus)
    except Exception as e:
        logging.error(f"ADS1115 configuration failed: {e}")
        return

    while True:
        try:
            with lock:
                raw = read_ads1115(i2c_bus)
                if raw is None:
                    logging.warning("ADS1115 read failed, retrying...")
                    time.sleep(1)
                    continue

                v = calculate_voltage(raw)
                p = calculate_charge(v)

                if v is not None and p is not None:
                    if abs(p - last_printed_charge) >= CHECK_DELTA:
                        print_battery_status(v, p)
                        last_printed_voltage = v
                        last_printed_charge = p

        except Exception as e:
            logging.error(f"Unexpected error: {e}")
            time.sleep(1)

        time.sleep(UPDATE_INTERVAL)

if __name__ == "__main__":
    main()
