import cv2
import numpy as np
import serial
import serial.tools.list_ports
import signal
import sys
import time
from gpiozero import LED
from threading import Thread

# Global variables
camera = None
serial_port = None
tracking_enabled = False
roi_center = (320, 240)
roi_half = 50
roi_top_left = (roi_center[0] - roi_half, roi_center[1] - roi_half)
roi_bottom_right = (roi_center[0] + roi_half, roi_center[1] + roi_half)

def find_serial_port():
    ports = list(serial.tools.list_ports.comports())
    for p in ports:
        if 'ACM' in p.device:
            return p.device
    for p in ports:
        if 'USB' in p.device:
            return p.device
    return None

def setup_serial():
    global serial_port
    port = find_serial_port()
    if port:
        try:
            serial_port = serial.Serial(port, 9600, timeout=1)
            print(f"Serial connected to {port}")
        except serial.SerialException as e:
            print(f"Serial error: {e}")
            serial_port = None
    else:
        print("No serial port found. Running in serial-disabled mode.")
        serial_port = None

def send_position(code):
    global serial_port
    if serial_port and serial_port.is_open:
        try:
            serial_port.write(str(code).encode())
        except serial.SerialException as e:
            print(f"Serial write error: {e}")
            serial_port.close()
            serial_port = None

def classify_position(x, y):
    center_x, center_y = roi_center
    dx = x - center_x
    dy = y - center_y
    if abs(dx) < roi_half and abs(dy) < roi_half:
        return '5'
    elif dx > roi_half and dy > roi_half:
        return '1'
    elif dx > roi_half and dy < -roi_half:
        return '2'
    elif dx < -roi_half and dy > roi_half:
        return '3'
    elif dx < -roi_half and dy < -roi_half:
        return '4'
    else:
        return '0'

def track_ball(frame):
    global tracking_enabled
    if not tracking_enabled:
        return

    roi = frame[roi_top_left[1]:roi_bottom_right[1], roi_top_left[0]:roi_bottom_right[0]]
    hsv = cv2.cvtColor(roi, cv2.COLOR_BGR2HSV)
    min_HSV = np.min(hsv, axis=(0, 1))
    max_HSV = np.max(hsv, axis=(0, 1))

    mask = cv2.inRange(hsv, min_HSV, max_HSV)
    contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

    for cnt in contours:
        area = cv2.contourArea(cnt)
        if area > 500:
            x, y, w, h = cv2.boundingRect(cnt)
            center_x = x + w // 2
            center_y = y + h // 2
            center_x += roi_top_left[0]
            center_y += roi_top_left[1]
            code = classify_position(center_x, center_y)
            if code != '0':
                send_position(code)
                cv2.rectangle(frame, (center_x - w // 2, center_y - h // 2),
                              (center_x + w // 2, center_y + h // 2), (255, 0, 0), 2)

def signal_handler(sig, frame):
    print("\nShutting down...")
    global camera, serial_port
    if camera:
        camera.release()
    if serial_port and serial_port.is_open:
        serial_port.close()
    cv2.destroyAllWindows()
    sys.exit(0)

def main():
    global camera, serial_port, tracking_enabled

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        camera = cv2.VideoCapture(0)
        if not camera.isOpened():
            print("Error: Could not open camera.")
            return

        setup_serial()

        tracking_enabled = False
        cv2.namedWindow("Tracking")
        cv2.setMouseCallback("Tracking", lambda event, x, y, flags, param: None)

        while True:
            ret, frame = camera.read()
            if not ret:
                print("Error: Failed to read frame.")
                break

            cv2.imshow("Tracking", frame)
            key = cv2.waitKey(1)

            if key == ord('s'):
                tracking_enabled = True
                print("Tracking enabled. Press 'o' to disable.")

            elif key == ord('o'):
                tracking_enabled = False
                print("Tracking disabled.")

            elif key == 27:
                print("Exiting...")
                break

            if tracking_enabled:
                track_ball(frame)

    except Exception as e:
        print(f"Error: {e}")
    finally:
        if camera:
            camera.release()
        if serial_port and serial_port.is_open:
            serial_port.close()
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

