import json
import time
import logging
import signal
import sys
from gpiozero import DistanceSensor, DeviceIgnored
from datetime import datetime
from threading import Lock
import os
import paho.mqtt.client as mqtt

# Configuration defaults
DEFAULT_CONFIG = {
    "sensors": [
        {"trigger": 17, "echo": 18, "offset": 0.0, "max_distance": 200.0},
        {"trigger": 22, "echo": 23, "offset": 0.0, "max_distance": 200.0},
        {"trigger": 24, "echo": 25, "offset": 0.0, "max_distance": 200.0}
    ],
    "alert_threshold_low": 10.0,
    "alert_threshold_high": 180.0,
    "alert_repeat_delay": 60,
    "log_file": "water_level.log"
}

# Initialize logging
logging.basicConfig(filename=DEFAULT_CONFIG["log_file"], level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

# Global state
sensor_data = []
last_alert_time = {}
alert_suppression = {}
sensor_errors = {}
sensor_excluded = {}
lock = Lock()
mqtt_client = None
mqtt_connected = False

def measure_distance(trigger_pin, echo_pin, offset, max_distance):
    try:
        # Create a DistanceSensor with the given pins
        sensor = DistanceSensor(trigger=trigger_pin, echo=echo_pin, echo_wait_time=0.05)
        distance = sensor.distance
        if distance is None:
            return None
        water_level = max_distance - distance
        return water_level
    except DeviceIgnored:
        return None
    except Exception as e:
        logging.error(f"Error measuring distance: {e}")
        return None

def read_config():
    try:
        with open("config.json", "r") as f:
            config = json.load(f)
        return config
    except (IOError, json.JSONDecodeError):
        logging.info("Config file not found or invalid. Using default configuration.")
        return DEFAULT_CONFIG

def setup_sensors(config):
    global sensor_data
    sensor_data = []
    for sensor in config["sensors"]:
        trigger = sensor["trigger"]
        echo = sensor["echo"]
        offset = sensor["offset"]
        max_distance = sensor["max_distance"]
        try:
            sensor_data.append({
                "trigger": trigger,
                "echo": echo,
                "offset": offset,
                "max_distance": max_distance,
                "last_error": 0,
                "excluded": False
            })
        except Exception as e:
            logging.error(f"Error setting up sensor {trigger}/{echo}: {e}")

def check_alerts():
    global last_alert_time, alert_suppression, sensor_data
    valid_readings = [s["water_level"] for s in sensor_data if s["water_level"] is not None]
    if not valid_readings:
        return
    avg_level = sum(valid_readings) / len(valid_readings)
    current_time = time.time()

    # Check low alert
    if avg_level < config["alert_threshold_low"]:
        if current_time - last_alert_time.get("low", 0) > config["alert_repeat_delay"]:
            logging.warning(f"Low water level alert: {avg_level:.2f} cm")
            last_alert_time["low"] = current_time
            if not mqtt_connected:
                logging.info("MQTT not connected, alert not sent.")
            else:
                mqtt_client.publish("water_level/alert", f"Low water level: {avg_level:.2f} cm")

    # Check high alert
    if avg_level > config["alert_threshold_high"]:
        if current_time - last_alert_time.get("high", 0) > config["alert_repeat_delay"]:
            logging.warning(f"High water level alert: {avg_level:.2f} cm")
            last_alert_time["high"] = current_time
            if not mqtt_connected:
                logging.info("MQTT not connected, alert not sent.")
            else:
                mqtt_client.publish("water_level/alert", f"High water level: {avg_level:.2f} cm")

def log_measurement(sensor_index, water_level):
    if water_level is not None:
        log_entry = f"{datetime.now()} - Sensor {sensor_index}: {water_level:.2f} cm\n"
        logging.info(log_entry)
        if mqtt_connected:
            mqtt_client.publish("water_level/data", log_entry.strip())

def handle_signal(signal, frame):
    logging.info("Shutting down gracefully...")
    for sensor in sensor_data:
        if not sensor["excluded"]:
            sensor["last_error"] += 1
            if sensor["last_error"] >= 5:
                sensor["excluded"] = True
                logging.warning(f"Sensor {sensor['trigger']}/{sensor['echo']} excluded after 5 consecutive errors.")
    sys.exit(0)

def main():
    global config, mqtt_client, mqtt_connected

    # Load configuration
    config = read_config()
    setup_sensors(config)

    # Initialize MQTT client
    mqtt_client = mqtt.Client()
    mqtt_client.on_connect = lambda client, userdata, flags, rc: on_mqtt_connect(client, userdata, flags, rc)
    mqtt_client.on_message = lambda client, userdata, msg: on_mqtt_message(client, userdata, msg)
    mqtt_client.connect_async("localhost", 1883, 60)
    mqtt_client.loop_start()
    mqtt_connected = False

    # Set up signal handler
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    # Initialize GPIO
    try:
        from gpiozero import Device
        Device.pin_factory = None  # Use physical pin numbering
    except Exception as e:
        logging.error(f"GPIO initialization failed: {e}")
        sys.exit(0)

    while True:
        try:
            for i, sensor in enumerate(sensor_data):
                if sensor["excluded"]:
                    continue
                water_level = measure_distance(sensor["trigger"], sensor["echo"], sensor["offset"], sensor["max_distance"])
                log_measurement(i, water_level)
                if water_level is None:
                    sensor["last_error"] += 1
                    if sensor["last_error"] >= 5:
                        sensor["excluded"] = True
                        logging.warning(f"Sensor {sensor['trigger']}/{sensor['echo']} excluded after 5 consecutive errors.")
                else:
                    sensor["last_error"] = 0
            check_alerts()
        except Exception as e:
            logging.error(f"Unexpected error: {e}")
        time.sleep(5)

def on_mqtt_connect(client, userdata, flags, rc):
    global mqtt_connected
    if rc == 0:
        logging.info("Connected to MQTT broker")
        mqtt_connected = True
    else:
        logging.error(f"Failed to connect to MQTT broker, return code {rc}")

def on_mqtt_message(client, userdata, msg):
    logging.info(f"Received message: {msg.payload.decode()} on topic {msg.topic}")

if __name__ == "__main__":
    main()

