                command = text.replace(WAKE_WORD, "").strip()
                if command in SUPPORTED_COMMANDS:
                    if command == "turn on the lights":
                        turn_lights_on()
                    elif command == "turn off the lights":
                        turn_lights_off()
                    elif command == "what is the temperature":
                        temp = read_temperature()
                        if temp is not None:
                            logging.info(f"Current temperature: {temp:.1f}°C")
                        else:
                            logging.info("Failed to read temperature.")
                    elif command == "take a picture":
                        image_path = capture_image(camera)
                        if image_path:
                            logging.info(f"Image saved as {image_path}")
                        else:
                            logging.info("Failed to capture image.")
                else:
                    logging.info("Unrecognized command.")
            else:
                logging.info("Command not recognized.")
        except sr.UnknownValueError:
            logging.info("Could not understand audio.")
        except sr.RequestError as e:
            logging.error(f"Could not request results from Google Speech Recognition service; {e}")
        except Exception as e:
            logging.error(f"Error during speech recognition: {e}")

def signal_handler(sig, frame):
    logging.info("Shutting down gracefully...")
    cleanup()
    sys.exit(0)

def cleanup():
    global gpio_initialized, camera_initialized, dht_initialized
    if gpio_initialized:
        try:
            GPIO.cleanup()
            logging.info("GPIO cleaned up.")
        except Exception as e:
            logging.error(f"Failed to clean up GPIO: {e}")
    if camera_initialized:
        try:
            camera.stop()
            logging.info("Camera resources released.")
        except Exception as e:
            logging.error(f"Failed to release camera resources: {e}")
    if dht_initialized:
        try:
            dht_sensor.exit()
            logging.info("DHT11 sensor closed.")
        except Exception as e:
            logging.error(f"Failed to close DHT11 sensor: {e}")

def main():
    setup_gpio()
    setup_dht_sensor()
    camera = setup_camera()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    logging.info("Greenhouse control system started.")
    try:
        while True:
            listen_for_commands()
            time.sleep(1)
    except KeyboardInterrupt:
        logging.info("Interrupt received, shutting down.")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

