import signal
import time
import logging
from gpiozero import Button, OutputDevice
from gpiozero import DeviceError
from contextlib import contextmanager

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# GPIO pin definitions using BCM numbering
INPUT_PINS = {
    'pin4': 4,
    'pin5': 5,
    'pin6': 6
}

OUTPUT_PINS = {
    'pin23': 23,
    'pin24': 24
}

# Initialize input buttons with internal pull-up resistors
input_buttons = {
    'pin4': Button(INPUT_PINS['pin4'], pull_up=True),
    'pin5': Button(INPUT_PINS['pin5'], pull_up=True),
    'pin6': Button(INPUT_PINS['pin6'], pull_up=True)
}

# Initialize output devices
output_devices = {
    'pin23': OutputDevice(OUTPUT_PINS['pin23'], initial_value=False),
    'pin24': OutputDevice(OUTPUT_PINS['pin24'], initial_value=False)
}

# Track the state of GPIO 24
gpio24_state = False

@contextmanager
def safe_gpio():
    try:
        yield
    except DeviceError as e:
        logging.error(f"GPIO initialization failed: {e}")
        exit(1)
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
        exit(1)
    finally:
        # Ensure all GPIO resources are released
        for dev in output_devices.values():
            dev.close()
        for btn in input_buttons.values():
            btn.close()

def handle_signal(signal, frame):
    logging.info("Received signal, cleaning up GPIO resources...")
    for dev in output_devices.values():
        dev.close()
    for btn in input_buttons.values():
        btn.close()
    exit(0)

def main():
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        with safe_gpio():
            while True:
                # Poll input pins every 0.05 seconds
                time.sleep(0.05)

                # Update GPIO 23 based on pin4 and pin5
                if input_buttons['pin4'].value == 0:
                    output_devices['pin23'].on()
                elif input_buttons['pin5'].value == 0:
                    output_devices['pin23'].off()

                # Toggle GPIO 24 if pin6 is pressed
                if input_buttons['pin6'].value == 0:
                    gpio24_state = not gpio24_state
                    output_devices['pin24'].value = gpio24_state

    except KeyboardInterrupt:
        logging.info("Keyboard interrupt received, cleaning up...")
    except Exception as e:
        logging.error(f"An error occurred: {e}")
    finally:
        for dev in output_devices.values():
            dev.close()
        for btn in input_buttons.values():
            btn.close()

if __name__ == "__main__":
    main()

