        raise

def setup_camera():
    try:
        picamera2 = Picamera2()
        config = picamera2.create_preview_configuration(main={"size": (CAMERA_WIDTH, CAMERA_HEIGHT), "format": CAMERA_FORMAT})
        picamera2.configure(config)
        print("Camera configuration completed.")
        return picamera2
    except Exception as e:
        print(f"Camera setup failed: {e}")
        raise

def create_image_directory():
    if not os.path.exists(IMAGE_DIR):
        try:
            os.makedirs(IMAGE_DIR)
            print(f"Directory '{IMAGE_DIR}' created.")
        except Exception as e:
            print(f"Failed to create directory '{IMAGE_DIR}': {e}")
            raise

def generate_timestamp():
    return time.strftime("%Y%m%d_%H%M%S")

def simulate_sensor_readings():
    temperature = round(random.uniform(*TEMPERATURE_RANGE), 1)
    humidity = round(random.uniform(*HUMIDITY_RANGE), 1)
    return temperature, humidity

