    except Exception as e:
        print(f"Failed to capture image: {e}")

def signal_handler(sig, frame):
    print("\nShutting down...")
    cleanup()
    exit(0)

def cleanup():
    try:
        if 'picamera2' in locals():
            picamera2.close()
        GPIO.cleanup()
    except Exception as e:
        print(f"Cleanup failed: {e}")

