import logging
import io
import numpy as np
import cv2
from picamera2 import Picamera2
from picamera2.encoders import MJPEGEncoder
from picamera2.outputs import FileOutput
from threading import Lock
import time

# Set up logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class CameraStreamBuffer:
    def __init__(self, c: Picamera2):
        self.c = c
        self.b = io.BytesIO()
        self.lock = Lock()
        self.frame_type = None
        self.current_config = None
        self.output_sink = None
        self.output_file = None
        self.output_writer = None
        self.output_started = False

    def start_output(self, output_sink):
        self.output_sink = output_sink
        self.output_file = open(output_sink, 'wb')
        self.output_writer = self.output_file.write
        self.output_started = True

    def stop_output(self):
        if self.output_started:
            self.output_file.close()
            self.output_started = False

    def write(self, d):
        with self.lock:
            try:
                self.b.write(d)
                config = self.c.current_configuration()
                if config and 'encode' in config:
                    self.current_config = config['encode']
                    if self.current_config['frame_type'] != 1:
                        if self.output_started:
                            self.output_writer(self.b.getvalue())
                            self.b = io.BytesIO()
                            self.frame_type = self.current_config['frame_type']
                        else:
                            logging.info("Output not started, buffer not flushed")
                    else:
                        self.frame_type = self.current_config['frame_type']
                else:
                    logging.warning("No valid encode configuration found in current frame")
            except IOError as e:
                logging.error(f"I/O error in write: {e}")
            except Exception as e:
                logging.error(f"Unexpected error in write: {e}")

    def flush(self):
        with self.lock:
            if self.b.tell() > 0:
                if self.output_started:
                    self.output_writer(self.b.getvalue())
                    self.b = io.BytesIO()
                else:
                    logging.info("Output not started, buffer not flushed")

    def __del__(self):
        self.stop_output()
        if self.b.tell() > 0:
            logging.warning("Buffer not flushed on exit")
        self.b.close()


class MotionDetectionBuffer:
    def __init__(self, callback):
        self.callback = callback
        self.b = io.BytesIO()
        self.previous_frame = None
        self.lock = Lock()
        self.soi_found = False
        self.current_frame = None
        self.frame_decoded = False
        self.soi_marker = b'\xff\xd8'
        self.last_soi_pos = 0
        self.frame_data = b''

    def write(self, d):
        with self.lock:
            try:
                self.frame_data += d
                if self.soi_marker in self.frame_data:
                    start_idx = self.frame_data.find(self.soi_marker)
                    if start_idx > self.last_soi_pos:
                        self.last_soi_pos = start_idx
                        self.b = io.BytesIO()
                        self.b.write(self.frame_data[start_idx:])
                        self.frame_data = b''
                        self.soi_found = True
                        self.frame_decoded = False
                    else:
                        self.soi_found = False
                if self.soi_found:
                    if not self.frame_decoded:
                        frame_bytes = self.b.getvalue()
                        np_arr = np.frombuffer(frame_bytes, dtype=np.uint8)
                        self.current_frame = cv2.imdecode(np_arr, cv2.IMREAD_COLOR)
                        if self.current_frame is not None:
                            if self.previous_frame is not None:
                                self.callback(self.previous_frame, self.current_frame)
                            self.previous_frame = self.current_frame
                            self.frame_decoded = True
                        else:
                            logging.warning("Failed to decode frame")
                    else:
                        self.soi_found = False
            except Exception as e:
                logging.error(f"Error in write: {e}")

    def __del__(self):
        if self.b.tell() > 0:
            logging.warning("Buffer not fully processed on exit")
        self.b.close()

