import os
import signal
import sys

# Constants
OLED_ADDRESS = 0x3C
I2C_BUS = 1
TEMPERATURE_FILE = "/sys/class/thermal/thermal_zone0/temp"
READ_INTERVAL = 2  # seconds

# Global variable to track if the program should exit
should_exit = False

def signal_handler(sig, frame):
    global should_exit
    should_exit = True

def initialize_i2c():
    try:
        return smbus2.SMBus(I2C_BUS)
    except Exception as e:
        print(f"Failed to initialize I2C bus {I2C_BUS}: {e}")
        sys.exit(1)

def read_cpu_temperature():
    try:
        with open(TEMPERATURE_FILE, 'r') as f:
            temp_millidegrees = int(f.read())
        return temp_millidegrees / 1000.0
    except FileNotFoundError:
        print(f"Temperature file not found: {TEMPERATURE_FILE}")
        sys.exit(1)
    except PermissionError:
        print(f"Permission denied when reading temperature file: {TEMPERATURE_FILE}")
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error reading temperature: {e}")
        sys.exit(1)

def main():
    global should_exit
    i2c_bus = None
    try:
        # Register signal handler for graceful exit
        signal.signal(signal.SIGINT, signal_handler)
        signal.signal(signal.SIGTERM, signal_handler)

        # Initialize I2C bus
        i2c_bus = initialize_i2c()

        while not should_exit:
            try:
                # Read CPU temperature
                cpu_temp = read_cpu_temperature()
                print(f"CPU Temperature: {cpu_temp:.2f}°C")
                time.sleep(READ_INTERVAL)
            except Exception as e:
                print(f"Error during reading: {e}")
                time.sleep(READ_INTERVAL)

    except Exception as e:
        print(f"Critical error in main loop: {e}")
        sys.exit(1)
    finally:
        if i2c_bus:
            try:
                i2c_bus.close()
                print("I2C bus closed properly.")
            except Exception as e:
                print(f"Error closing I2C bus: {e}")

if __name__ == "__main__":
    main()

import smbus2
import time
import signal
import sys

# I2C configuration
I2C_ADDRESS = 0x20
I2C_BUS = 1  # Default for Raspberry Pi 3/4 (physical pins 3 and 5)

# Register addresses
OUTPUT_PORT_REGISTER = 0x00
INPUT_PORT_REGISTER = 0x01

# Sensor configuration
SENSOR_COUNT = 8
POLL_INTERVAL = 0.1  # 100 milliseconds

# Global variables
i2c_bus = None
sensor_states = [False] * SENSOR_COUNT
running = True

def signal_handler(sig, frame):
    global running
    print("\nShutting down...")
    running = False

def setup_i2c():
    global i2c_bus
    try:
        i2c_bus = smbus2.SMBus(I2C_BUS)
        print("I2C bus initialized successfully.")
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        sys.exit(1)

def configure_expander():
    try:
        # Set all pins as inputs with internal pull-up
        i2c_bus.write_byte_data(I2C_ADDRESS, OUTPUT_PORT_REGISTER, 0xFF)
        print("Expander configured as inputs with pull-ups.")
    except Exception as e:
        print(f"Error configuring expander: {e}")
        sys.exit(1)

def read_sensor_states():
    try:
        # Read input port register
        data = i2c_bus.read_byte_data(I2C_ADDRESS, INPUT_PORT_REGISTER)
        return data
    except Exception as e:
        print(f"I2C read error: {e}")
        return None

def check_sensors():
    global sensor_states
    data = read_sensor_states()
    if data is None:
        return

    for i in range(SENSOR_COUNT):
        # Check if sensor is LOW (obstacle detected)
        if not (data & (1 << i)):
            if not sensor_states[i]:
                print(f"Obstacle detected by sensor {i}")
                sensor_states[i] = True
        else:
            if sensor_states[i]:
                sensor_states[i] = False

def main():
    global running
    setup_i2c()
    configure_expander()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        while running:
            check_sensors()
            time.sleep(POLL_INTERVAL)
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    finally:
        print("Cleaning up...")
        if i2c_bus:
            try:
                i2c_bus.close()
            except Exception as e:
                print(f"Error closing I2C bus: {e}")
        sys.exit(0)

if __name__ == "__main__":
    main()

