import logging
import time
import smbus2
from typing import Tuple, Optional

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class DHT20Sensor:
    def __init__(self, i2c_bus: int = 1, i2c_address: int = 0x38):
        self.i2c_bus = i2c_bus
        self.i2c_address = i2c_address
        self.bus = None
        self._initialized = False
        self._initialize()

    def _initialize(self):
        try:
            self.bus = smbus2.SMBus(self.i2c_bus)
            time.sleep(0.5)  # Wait for power stabilization
            status = self._read_register(0x71)
            if (status & 0x18) != 0x18:
                logging.error("DHT20 sensor not found or status check failed.")
                self._close()
                self._initialized = False
                return False
            self._initialized = True
            return True
        except Exception as e:
            logging.error(f"Failed to initialize DHT20 sensor: {e}")
            self._close()
            self._initialized = False
            return False

    def _close(self):
        if self.bus:
            try:
                self.bus.close()
            except Exception as e:
                logging.error(f"Error closing I2C bus: {e}")
            self.bus = None

    def _read_register(self, reg: int) -> int:
        try:
            return self.bus.read_byte_data(self.i2c_address, reg)
        except Exception as e:
            logging.error(f"Error reading from register 0x{reg:02X}: {e}")
            self._close()
            raise

    def _write_register(self, reg: int, value: int):
        try:
            self.bus.write_byte_data(self.i2c_address, reg, value)
        except Exception as e:
            logging.error(f"Error writing to register 0x{reg:02X}: {e}")
            self._close()
            raise

    def _calculate_crc8(self, data: bytes) -> int:
        crc = 0xFF
        polynomial = 0x31
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = (crc << 1) ^ polynomial
                else:
                    crc <<= 1
        return crc & 0xFF

    def _get_raw_data(self) -> Tuple[bytes, int]:
        try:
            self._write_register(0xAC, 0x33)
            self._write_register(0xAC, 0x00)
            start_time = time.time()
            while True:
                status = self._read_register(0x71)
                if (status & 0x80) == 0:
                    break
                if time.time() - start_time > 0.1:
                    logging.warning("Timeout waiting for measurement completion.")
                    return None, 1
                time.sleep(0.01)
            data = self.bus.read_i2c_block_data(self.i2c_address, 0x71, 7)
            return data, status
        except Exception as e:
            logging.error(f"Error reading data from DHT20: {e}")
            self._close()
            raise

    def _process_data(self, data: bytes, status: int) -> Tuple[float, float, bool]:
        if len(data) < 7:
            logging.warning("Incomplete data received from DHT20.")
            return None, None, True

        raw_humidity = (data[0] << 16) | (data[1] << 8) | data[2]
        raw_temperature = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4)
        crc = data[6]

        calculated_crc = self._calculate_crc8(data[:6])
        if calculated_crc != crc:
            logging.warning("CRC checksum failed for DHT20 data.")
            return None, None, True

        humidity = raw_humidity / 1048576 * 100
        temperature = raw_temperature / 5242.88 - 50
        return temperature, humidity, False

    def get_temperature_and_humidity(self) -> Tuple[Optional[float], Optional[float], bool]:
        if not self._initialized:
            logging.error("DHT20 sensor not initialized.")
            return None, None, True

        for attempt in range(5):
            try:
                data, status = self._get_raw_data()
                if data is None:
                    continue
                temperature, humidity, crc_error = self._process_data(data, status)
                if temperature is not None and humidity is not None and not crc_error:
                    return temperature, humidity, crc_error
                else:
                    logging.warning("Data processing failed, retrying...")
                    time.sleep(2)
            except Exception as e:
                logging.error(f"Error during measurement attempt {attempt + 1}: {e}")
                time.sleep(2)
                continue
        logging.error("Failed to get valid data from DHT20 after 5 attempts.")
        return None, None, True

    def __del__(self):
        self._close()

