import RPi.GPIO as GPIO
import time
import csv
from datetime import datetime

DHT_PIN = 4
LOG_FILE = 'humidity_log.txt'
READ_INTERVAL = 10  # seconds
MAX_WAIT = 1000000  # microseconds
PULSE_THRESHOLD_0 = 26  # microseconds
PULSE_THRESHOLD_1 = 70  # microseconds

def setup_gpio():
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(DHT_PIN, GPIO.OUT)
        GPIO.output(DHT_PIN, GPIO.LOW)
        time.sleep(0.01)
        GPIO.output(DHT_PIN, GPIO.HIGH)
        GPIO.setup(DHT_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        return True
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        return False

def read_dht22():
    data = []
    start_time = time.time()
    while time.time() - start_time < 0.1:
        if GPIO.input(DHT_PIN) == GPIO.LOW:
            break
    else:
        return (None, None)

    start_time = time.time()
    while time.time() - start_time < 0.1:
        if GPIO.input(DHT_PIN) == GPIO.HIGH:
            break
    else:
        return (None, None)

    for _ in range(40):
        start_time = time.time()
        while GPIO.input(DHT_PIN) == GPIO.LOW:
            pass
        pulse_duration = time.time() - start_time
        if pulse_duration > MAX_WAIT / 1e6:
            return (None, None)
        start_time = time.time()
        while GPIO.input(DHT_PIN) == GPIO.HIGH:
            pass
        pulse_duration = time.time() - start_time
        if pulse_duration < PULSE_THRESHOLD_0:
            data.append(0)
        elif pulse_duration < PULSE_THRESHOLD_1:
            data.append(1)
        else:
            return (None, None)

    humidity = (data[0] << 8) | data[1]
    temperature = (data[2] << 8) | data[3]
    checksum = data[4]

    if (humidity + temperature) % 256 != checksum:
        return (None, None)

    humidity = humidity / 10.0
    temperature = temperature / 10.0
    if temperature > 125:
        temperature -= 256
    return (temperature, humidity)

def log_data(temperature, humidity):
    if temperature is None or humidity is None:
        return
    now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    with open(LOG_FILE, 'a', newline='') as f:
        writer = csv.writer(f)
        writer.writerow([now, temperature, humidity])

def main():
    if not setup_gpio():
        print("Failed to setup GPIO. Exiting.")
        return

    try:
        while True:
            temperature, humidity = read_dht22()
            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                log_data(temperature, humidity)
            else:
                print("Failed to read DHT22 sensor. Retrying...")
            time.sleep(READ_INTERVAL)
    except KeyboardInterrupt:
        print("\nKeyboardInterrupt received. Cleaning up...")
    finally:
        GPIO.cleanup()

if __name__ == "__main__":
    main()

