logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class DHT20Sensor:
    def __init__(self, i2c_bus=1, i2c_address=0x38):
        self.i2c_bus = i2c_bus
        self.i2c_address = i2c_address
        self.bus = None
        self._setup_i2c()

    def _setup_i2c(self):
        try:
            self.bus = smbus2.SMBus(self.i2c_bus)
            # Verify sensor presence by reading status register
            status = self.bus.read_byte_data(self.i2c_address, 0x71)
            if status != 0x71:
                logging.error("DHT20 sensor not found at address 0x38 on I2C bus %d", self.i2c_bus)
                self.bus = None
        except Exception as e:
            logging.error("Failed to initialize I2C bus or read sensor status: %s", e)
            self.bus = None

    def _crc8(self, data):
        """Calculate CRC-8 checksum using polynomial 0x31, initial value 0xFF."""
        crc = 0xFF
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = (crc << 1) ^ 0x31
                else:
                    crc <<= 1
        return crc

    def measure(self):
        if not self.bus:
            logging.error("I2C bus not initialized or sensor not found.")
            return (None, None, True)

        try:
            # Send measurement command: 0x33 (start measurement), 0x00 (no hold)
            self.bus.write_i2c_block_data(self.i2c_address, 0xAC, [0x33, 0x00])
            time.sleep(0.05)  # Wait for measurement to start

            # Wait for measurement to complete (bit 7 of status register 0x71 must be 0)
            timeout = 0.1
            start_time = time.time()
            while True:
                status = self.bus.read_byte_data(self.i2c_address, 0x71)
                if (status & 0x80) == 0:
                    break
                if time.time() - start_time > timeout:
                    logging.error("Measurement timeout waiting for DHT20 to complete.")
                    return (None, None, True)
                time.sleep(0.01)

            # Read 7 bytes of data starting from register 0x71
            data = self.bus.read_i2c_block_data(self.i2c_address, 0x71, 7)
            if len(data) != 7:
                logging.error("Failed to read 7 bytes from DHT20 sensor.")
                return (None, None, True)

            # Check CRC-8
            crc = self._crc8(data[:6])
            crc_error = (crc != data[6])

            # Extract raw values
            humidity_raw = (data[1] << 16) | (data[2] << 8) | data[3]
            temperature_raw = (data[3] << 16) | (data[4] << 8) | data[5]

            # Convert to float
            humidity = float(humidity_raw) / 0x100000 * 100.0
            temperature = float(temperature_raw) / 5242.88 - 50.0

            return (temperature, humidity, crc_error)

        except Exception as e:
            logging.error("Error during measurement: %s", e)
            return (None, None, True)

    def close(self):
        if self.bus:
            try:
                self.bus.close()
            except Exception as e:
                logging.error("Error closing I2C bus: %s", e)
            self.bus = None

def signal_handler(sig, frame):
    logging.info("Received signal %d, shutting down...", sig)
    sensor.close()
    sys.exit(0)

if __name__ == "__main__":
    sensor = DHT20Sensor()
    if sensor.bus:
        signal.signal(signal.SIGINT, signal_handler)
        signal.signal(signal.SIGTERM, signal_handler)
        try:
