            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.2f}°C, Humidity: {humidity:.2f}% RH, CRC Error: {crc_error}")
            else:
                print("Measurement failed.")
        finally:
            sensor.close()
    else:
        print("Failed to initialize DHT20 sensor.")

