import RPi.GPIO as GPIO
import time

# Configuration
DATA_PIN = 4  # BCM GPIO4 (physical pin 7)
MAX_RETRIES = 3
RETRY_DELAY = 2
CHECK_DELAY = 5
READ_DELAY = 5

# DHT22 signal timing constants
PULSE_LOW = 18  # ms
PULSE_HIGH = 80  # µs
PULSE_LOW_RESPONSE = 80  # µs
PULSE_HIGH_RESPONSE = 80  # µs

# DHT22 data format
DATA_BYTES = 5  # humidity_int, humidity_dec, temperature_int, temperature_dec, checksum

def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(DATA_PIN, GPIO.OUT)
    GPIO.output(DATA_PIN, GPIO.HIGH)
    return True

def gpio_cleanup():
    GPIO.cleanup()
    return True

def pulse_low(pin, duration):
    GPIO.output(pin, GPIO.LOW)
    time.sleep(duration / 1000)
    GPIO.output(pin, GPIO.HIGH)

def pulse_high(pin, duration):
    GPIO.output(pin, GPIO.HIGH)
    time.sleep(duration / 1000000)

def read_data(pin):
    # Send start signal
    pulse_low(pin, PULSE_LOW)
    time.sleep(0.01)  # Wait for sensor to respond

    # Wait for response
    start_time = time.time()
    while GPIO.input(pin) == GPIO.LOW:
        if time.time() - start_time > 0.1:
            return None  # Timeout

    # Wait for 80 µs high
    while GPIO.input(pin) == GPIO.HIGH:
        if time.time() - start_time > 0.0001:
            return None  # Timeout

    # Read 40 bits
    data = []
    for _ in range(DATA_BYTES):
        start_time = time.time()
        while GPIO.input(pin) == GPIO.LOW:
            if time.time() - start_time > 0.0001:
                return None  # Timeout
        # Wait for high
        while GPIO.input(pin) == GPIO.HIGH:
            if time.time() - start_time > 0.0001:
                return None  # Timeout
        # Read bit
        if time.time() - start_time > 0.00005:
            data.append(1)
        else:
            data.append(0)

    # Convert data to bytes
    data_bytes = [0] * DATA_BYTES
    for i in range(DATA_BYTES):
        data_bytes[i] = 0
        for j in range(8):
            data_bytes[i] = (data_bytes[i] << 1) | data[j + i * 8]

    # Check checksum
    checksum = data_bytes[4]
    if (data_bytes[0] + data_bytes[1] + data_bytes[2] + data_bytes[3]) % 256 != checksum:
        return None

    # Extract temperature and humidity
    humidity = data_bytes[0] + (data_bytes[1] / 100)
    temperature = data_bytes[2] + (data_bytes[3] / 100)
    return humidity, temperature

def read_dht22():
    for attempt in range(MAX_RETRIES):
        try:
            if setup_gpio():
                data = read_data(DATA_PIN)
                if data:
                    humidity, temperature = data
                    print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                    return True
                else:
                    print("DHT22 read failed - timeout or invalid data")
                    time.sleep(RETRY_DELAY)
            else:
                print("GPIO setup failed")
                time.sleep(RETRY_DELAY)
        except Exception as e:
            print(f"Error reading DHT22: {e}")
            time.sleep(RETRY_DELAY)
    print("DHT22 read failed after multiple attempts")
    time.sleep(CHECK_DELAY)
    return False

def main():
    try:
        while True:
            if read_dht22():
                time.sleep(READ_DELAY)
            else:
                time.sleep(CHECK_DELAY)
    except KeyboardInterrupt:
        print("\nCtrl+C detected. Cleaning up...")
    finally:
        gpio_cleanup()

if __name__ == "__main__":
    main()

