import logging
import time
import smbus2
from contextlib import contextmanager
from typing import Tuple, Optional

# Configure logging
logging.basicConfig(level=logging.WARNING, format='%(asctime)s - %(levelname)s - %(message)s')

class DHT20Sensor:
    I2C_BUS = 1
    I2C_ADDRESS = 0x38
    STATUS_REGISTER = 0x71
    MEASUREMENT_REGISTER = 0xAC
    MAX_MEASUREMENT_ATTEMPTS = 5
    MEASUREMENT_RETRY_DELAY = 0.01
    MAX_POLL_ATTEMPTS = 10
    POLL_DELAY = 0.08
    CRC_POLYNOMIAL = 0x31
    CRC_INITIAL = 0xFF

    def __init__(self):
        self.bus = None
        self.last_measurement_time = 0
        self.last_result = (None, None, False)
        self._is_initialized = False

    def _crc8(self, data: bytes) -> int:
        crc = self.CRC_INITIAL
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = (crc << 1) ^ self.CRC_POLYNOMIAL
                else:
                    crc <<= 1
        return crc

    def _read_status(self) -> int:
        try:
            status = self.bus.read_byte_data(self.I2C_ADDRESS, self.STATUS_REGISTER)
            return status
        except OSError as e:
            logging.warning(f"I2C read error: {e}")
            return -1

    def _write_measurement_command(self):
        try:
            self.bus.write_i2c_block_data(self.I2C_ADDRESS, self.MEASUREMENT_REGISTER, [0x33, 0x00])
        except OSError as e:
            logging.warning(f"I2C write error: {e}")
            return False
        return True

    def _wait_for_idle(self, max_attempts: int = MAX_POLL_ATTEMPTS) -> bool:
        for _ in range(max_attempts):
            status = self._read_status()
            if status == -1:
                return False
            if (status & 0x18) == 0x18:
                time.sleep(self.POLL_DELAY)
            else:
                return True
        return False

    def _read_data(self) -> Tuple[int, int, int]:
        try:
            data = self.bus.read_i2c_block_data(self.I2C_ADDRESS, self.STATUS_REGISTER, 7)
            crc = self._crc8(data[:6])
            if crc != data[6]:
                logging.warning("CRC checksum mismatch")
                return -1, -1, False
            return data, True, False
        except OSError as e:
            logging.warning(f"I2C read error: {e}")
            return -1, -1, True

    def _process_data(self, data: bytes) -> Tuple[float, float]:
        humidity_raw = ((data[1] << 12) | (data[2] << 4) | ((data[3] & 0xF0) >> 4))
        humidity = humidity_raw / (2 ** 20) * 100

        temperature_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5])
        temperature = temperature_raw / (2 ** 19) * 200 - 50

        return humidity, temperature

    def begin(self) -> bool:
        try:
            self.bus = smbus2.SMBus(self.I2C_BUS)
            time.sleep(0.5)
            status = self._read_status()
            if status == -1:
                logging.error("Failed to open I2C bus")
                return False
            if (status & 0x18) != 0x18:
                logging.error("Status register not in expected state")
                return False
            self._is_initialized = True
            return True
        except Exception as e:
            logging.error(f"Initialization error: {e}")
            return False

    def get_temperature_and_humidity(self) -> Tuple[Optional[float], Optional[float], bool]:
        current_time = time.time()
        if current_time - self.last_measurement_time < 2:
            return self.last_result

        for attempt in range(self.MAX_MEASUREMENT_ATTEMPTS):
            if not self._is_initialized:
                logging.warning("Sensor not initialized")
                return (None, None, True)

            if not self._write_measurement_command():
                logging.warning("Failed to trigger measurement")
                return (None, None, True)

            if not self._wait_for_idle():
                logging.warning("Measurement timed out")
                return (None, None, True)

            data, success, error = self._read_data()
            if not success:
                if error:
                    logging.warning("Measurement failed with error")
                else:
                    logging.warning("CRC error in measurement data")
                time.sleep(self.MEASUREMENT_RETRY_DELAY)
                continue

            humidity, temperature = self._process_data(data)
            self.last_result = (humidity, temperature, False)
            self.last_measurement_time = current_time
            return self.last_result

        logging.error("All measurement attempts failed")
        return (None, None, True)

    def close(self):
        if self.bus:
            self.bus.close()
            self.bus = None
            self._is_initialized = False

    def __enter__(self):
        if not self.begin():
            logging.error("Failed to initialize sensor")
            return self
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close()

    def __del__(self):
        self.close()


def demo():
    sensor = DHT20Sensor()
    try:
        with sensor:
            while True:
                humidity, temperature, error = sensor.get_temperature_and_humidity()
                if error:
                    print("Measurement failed")
                else:
                    print(f"Humidity: {humidity:.2f}%, Temperature: {temperature:.2f}°C")
                time.sleep(1)
    except KeyboardInterrupt:
        print("\nDemo interrupted by user")
    except SystemExit:
        print("\nDemo exited")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        sensor.close()


if __name__ == "__main__":
    try:
        demo()
    except Exception as e:
        print(f"Demo failed: {e}")
        exit(0)

