import sys

# Configuration
GPIO_HUMIDITY_1 = 17
GPIO_TEMPERATURE_1 = 17
GPIO_HUMIDITY_2 = 27
GPIO_TEMPERATURE_2 = 27
CSV_FILE_TEMPLATE = "retail_data_{}.csv"
ALERT_LOG = "retail_alerts.log"
ERROR_LOG = "error.log"
CLOUD_LOG = "cloud_log.log"
ALERT_HUMIDITY_THRESHOLD_HIGH = 75
ALERT_HUMIDITY_THRESHOLD_LOW = 45
ALERT_CONSECUTIVE_COUNT = 3
ALERT_DEBOUNCE_TIME = 1800  # 30 minutes in seconds
READ_RETRY_COUNT = 3
READ_RETRY_DELAY = 2
CSV_WRITE_INTERVAL = 60
MQTT_TOPIC = "sensor/alerts"
MQTT_BROKER = "localhost"
MQTT_PORT = 1883
MQTT_CLIENT_ID = "sensor_client"

# Setup logging
logging.basicConfig(
    filename=ERROR_LOG,
    level=logging.ERROR,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Initialize sensors
try:
    dht1 = DHT22(GPIO_HUMIDITY_1, use_pulseio=False)
    dht2 = DHT22(GPIO_HUMIDITY_2, use_pulseio=False)
except Exception as e:
    logging.error(f"Sensor initialization failed: {e}")
    sys.exit(1)

# Alert tracking
last_alert_time = {}
alert_log = {}

# File locking
def lock_file(file_path):
    try:
        with open(file_path, 'a') as f:
            fcntl.flock(f, fcntl.LOCK_EX | fcntl.LOCK_NB)
    except Exception as e:
        logging.error(f"Failed to lock file {file_path}: {e}")
        return False
    return True

def unlock_file(file_path):
    try:
        with open(file_path, 'a') as f:
            fcntl.flock(f, fcntl.LOCK_UN)
    except Exception as e:
        logging.error(f"Failed to unlock file {file_path}: {e}")

def write_csv(data, file_path):
    try:
        if not lock_file(file_path):
            return False
        with open(file_path, 'a', newline='') as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow(data)
        unlock_file(file_path)
        return True
    except Exception as e:
        logging.error(f"CSV write error: {e}")
        return False

def log_alert(sensor_id, alert_type):
    now = datetime.now()
    log_entry = f"{now} - {alert_type} - Sensor {sensor_id}\n"
    with open(ALERT_LOG, 'a') as f:
        f.write(log_entry)
    if sensor_id not in last_alert_time or now.timestamp() - last_alert_time[sensor_id] > ALERT_DEBOUNCE_TIME:
        last_alert_time[sensor_id] = now.timestamp()
        try:
            client.publish(MQTT_TOPIC, f"{sensor_id}:{alert_type}", qos=1)
        except Exception as e:
            logging.error(f"MQTT publish failed: {e}")

def send_to_cloud(data):
    try:
        if random.random() < 0.8:
            client.publish(MQTT_TOPIC, data, qos=1)
            logging.info(f"Cloud push successful: {data}")
        else:
            logging.info(f"Cloud push failed: {data}")
    except Exception as e:
        logging.error(f"Cloud push error: {e}")

def read_sensor(sensor, sensor_id):
    for _ in range(READ_RETRY_COUNT):
        try:
            humidity = sensor.humidity
            temperature = sensor.temperature
            if 0 <= humidity <= 100 and 0 <= temperature <= 35:
                return humidity, temperature
            else:
                logging.warning(f"Invalid reading for sensor {sensor_id}: humidity={humidity}, temperature={temperature}")
        except Exception as e:
            logging.warning(f"Sensor read failed for {sensor_id}: {e}")
        time.sleep(READ_RETRY_DELAY)
    return None, None

def check_alerts(humidities, sensor_ids):
    for i, humidity in enumerate(humidities):
        sensor_id = sensor_ids[i]
        if humidity > ALERT_HUMIDITY_THRESHOLD_HIGH:
            if alert_log.get(sensor_id, 0) < ALERT_CONSECUTIVE_COUNT:
                alert_log[sensor_id] = alert_log.get(sensor_id, 0) + 1
            else:
                log_alert(sensor_id, "High Humidity")
                alert_log[sensor_id] = 0
        elif humidity < ALERT_HUMIDITY_THRESHOLD_LOW:
            if alert_log.get(sensor_id, 0) < ALERT_CONSECUTIVE_COUNT:
                alert_log[sensor_id] = alert_log.get(sensor_id, 0) + 1
            else:
                log_alert(sensor_id, "Low Humidity")
                alert_log[sensor_id] = 0
        else:
            alert_log[sensor_id] = 0

def main():
    global client
    client = mqtt.Client(client_id=MQTT_CLIENT_ID)
    client.connect(MQTT_BROKER, MQTT_PORT, 60)

    try:
        while True:
            try:
                humidity1, temp1 = read_sensor(dht1, "1")
                humidity2, temp2 = read_sensor(dht2, "2")
                if humidity1 is not None and temp1 is not None and humidity2 is not None and temp2 is not None:
                    now = datetime.now()
                    date_str = now.strftime("%Y-%m-%d")
                    csv_file = CSV_FILE_TEMPLATE.format(date_str)
                    data = [now.strftime("%Y-%m-%d %H:%M:%S"), humidity1, temp1, humidity2, temp2]
                    if write_csv(data, csv_file):
                        check_alerts([humidity1, humidity2], ["1", "2"])
                        send_to_cloud(f"Sensor Data: {data}")
                    else:
                        logging.warning("Failed to write to CSV file")
                else:
                    logging.warning("Failed to read sensor data")
            except Exception as e:
                logging.error(f"Unexpected error: {e}")
                logging.error(traceback.format_exc())
            time.sleep(CSV_WRITE_INTERVAL)
    except KeyboardInterrupt:
        logging.info("Script interrupted by user")
    finally:
        try:
            client.disconnect()
        except:
            pass
        dht1.exit()
        dht2.exit()

def signal_handler(sig, frame):
    logging.info("Shutting down gracefully...")
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    main()

