import sys
import time
import signal
import logging
from smbus2 import SMBus, i2c_msg
from ina219 import INA219
from ina219 import DeviceRange
from adafruit_bus_device.i2c_device import I2CDevice
from adafruit_register.i2c_bit import Bit
from adafruit_register.i2c_struct import Struct
from enum import Enum
import threading

# Set up logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
I2C_BUS = 1
INA219_POWER_SUPPLY_ADDR = 0x40
INA219_BATTERY_ADDR = 0x45
UPS_CONTROLLER_ADDR = 0x17
SHUNT_RESISTANCE_POWER = 0.00725  # Ohms
SHUNT_RESISTANCE_BATTERY = 0.005  # Ohms

# Register offsets for UPS controller
UPS_REGISTER_FIELDS = {
    "processor_voltage": (0x01, 0x02),
    "raspberry_pi_voltage": (0x03, 0x04),
    "battery_port_voltage": (0x05, 0x06),
    "type_c_charging_voltage": (0x07, 0x08),
    "micro_usb_charging_voltage": (0x09, 0x0A),
    "battery_temperature": (0x0B, 0x0C),
    "full_battery_voltage": (0x0D, 0x0E),
    "empty_battery_voltage": (0x0F, 0x10),
    "battery_protection_voltage": (0x11, 0x12),
    "remaining_capacity_percent": (0x13, 0x14),
    "sampling_period_minutes": (0x15, 0x16),
    "power_state": (0x17, 0x17),
    "shutdown_countdown_seconds": (0x18, 0x18),
    "auto_power_on": (0x19, 0x19),
    "restart_countdown_seconds": (0x1A, 0x1A),
}

# Define PowerState enum
class PowerState(Enum):
    OFF = 0
    ON = 1
    CHARGING = 2
    DISCHARGING = 3
    UNKNOWN = 4

# Define UPSController class
class UPSController:
    def __init__(self, i2c_bus, address):
        self.i2c_bus = i2c_bus
        self.address = address
        self.device = I2CDevice(self.i2c_bus, self.address)
        self._init_registers()

    def _init_registers(self):
        try:
            self._read_register(0x00, 256)
        except Exception as e:
            logging.error(f"Failed to initialize UPS controller registers: {e}")
            raise

    def _read_register(self, reg, length=1):
        try:
            with self.device as i2c:
                read = i2c_msg.read(self.address, length)
                i2c.write(read)
                data = list(read)
            return data
        except Exception as e:
            logging.error(f"Error reading register 0x{reg:02X}: {e}")
            raise

    def read_register(self, reg):
        return self._read_register(reg, 1)[0]

    def read_registers(self, reg, length):
        return self._read_register(reg, length)

    def read_field(self, field_name):
        reg_start, reg_end = UPS_REGISTER_FIELDS[field_name]
        if reg_start == reg_end:
            data = self.read_register(reg_start)
        else:
            data = self.read_registers(reg_start, 2)
        return (data[0] << 8) | data[1]

    def read_all_registers(self):
        return self.read_registers(0x00, 256)

# Define INA219Sensor class
class INA219Sensor:
    def __init__(self, i2c_bus, address, shunt_resistance):
        self.i2c_bus = i2c_bus
        self.address = address
        self.shunt_resistance = shunt_resistance
        self.sensor = INA219(i2c_bus, address, shunt_resistance)
        self._check_sensor()

    def _check_sensor(self):
        try:
            self.sensor.configure(INA219.CONFIG_BUS_VOLTS | INA219.CONFIG_SHUNT_OV | INA219.CONFIG_ADC_BITS_12)
        except Exception as e:
            logging.error(f"Failed to initialize INA219 sensor at 0x{self.address:02X}: {e}")
            raise

    def read_voltage(self):
        try:
            return self.sensor.bus_voltage
        except Exception as e:
            logging.error(f"Error reading voltage from INA219 sensor at 0x{self.address:02X}: {e}")
            return None

    def read_current(self):
        try:
            return self.sensor.current
        except Exception as e:
            logging.error(f"Error reading current from INA219 sensor at 0x{self.address:02X}: {e}")
            return None

    def read_power(self):
        try:
            return self.sensor.power
        except Exception as e:
            logging.error(f"Error reading power from INA219 sensor at 0x{self.address:02X}: {e}")
            return None

# Define UPSPlus class
class UPSPlus:
    def __init__(self, i2c_bus, address):
        self.i2c_bus = i2c_bus
        self.address = address
        self.controller = UPSController(i2c_bus, address)

    def read_all_registers(self):
        return self.controller.read_all_registers()

    def read_field(self, field_name):
        return self.controller.read_field(field_name)

# Main class
class UPSMonitor:
    def __init__(self, i2c_bus):
        self.i2c_bus = i2c_bus
        self.power_supply_sensor = None
        self.battery_sensor = None
        self.ups_plus = None
        self._init_sensors()
        self._init_ups_plus()

    def _init_sensors(self):
        try:
            self.power_supply_sensor = INA219Sensor(self.i2c_bus, INA219_POWER_SUPPLY_ADDR, SHUNT_RESISTANCE_POWER)
        except Exception as e:
