            logging.error(f"Failed to initialize UPS controller registers: {e}")
            raise

    def _read_register(self, reg, length=1):
        try:
            with self.device as i2c:
                read = i2c_msg.read(self.address, length)
                i2c.write(read)
                data = list(read)
            return data
        except Exception as e:
            logging.error(f"Error reading register 0x{reg:02X}: {e}")
            raise

    def read_register(self, reg):
        return self._read_register(reg, 1)[0]

    def read_registers(self, reg, length):
        return self._read_register(reg, length)

    def read_field(self, field_name):
        reg_start, reg_end = UPS_REGISTER_FIELDS[field_name]
        if reg_start == reg_end:
            data = self.read_register(reg_start)
        else:
            data = self.read_registers(reg_start, 2)
