    led.close()
    pir_sensor.close()
    print("GPIO resources released.")

def main():
    print("Starting motion detection system...")
    try:
        while True:
            motion_detected = pir_sensor.value
            if motion_detected:
                led.on()
                if not send_http_request("on"):
                    print("Failed to send HTTP request, LED remains on.")
            else:
                led.off()
                if not send_http_request("off"):
                    print("Failed to send HTTP request, LED remains off.")
            time.sleep(PIR_POLL_INTERVAL)
    except KeyboardInterrupt:
        shutdown()
    except Exception as e:
        print(f"Unexpected error: {e}")
        shutdown()
        sys.exit(1)

