    "Starting sensor monitoring program.\n"
    f"Monitoring pins: {', '.join(SENSOR_PINS.values())}\n"
    f"Polling interval: {POLL_INTERVAL} seconds\n"
)

# Initialize sensors with active-high pull-up
sensors = {
    'sensor1': DigitalInputDevice(SENSOR_PINS['sensor1'], pull_up=True),
    'sensor2': DigitalInputDevice(SENSOR_PINS['sensor2'], pull_up=True),
    'sensor3': DigitalInputDevice(SENSOR_PINS['sensor3'], pull_up=True)
}

def setup_sensors():
    """Initialize all sensors and handle any initialization errors."""
    for sensor in sensors.values():
        try:
            sensor.wait_for_active(timeout=0.1)
        except Exception as e:
            print(f"Error initializing sensor: {e}")
            return False
    return True

def poll_sensors():
    """Poll each sensor and print response if HIGH."""
    for sensor_name, sensor in sensors.items():
        try:
            if sensor.value:
                print(f"Response for {sensor_name}")
        except Exception as e:
            print(f"Error reading {sensor_name}: {e}")

def signal_handler(signal, frame):
    """Handle graceful shutdown on SIGTERM or KeyboardInterrupt."""
    print("\nShutting down gracefully...")
    for sensor in sensors.values():
        sensor.close()
    exit(0)

def main():
    print(STARTUP_MESSAGE)
    if not setup_sensors():
        print("Failed to initialize sensors. Exiting.")
        return

    signal(SIGTERM, signal_handler)
    signal(KeyboardInterrupt, signal_handler)

    try:
        while True:
            poll_sensors()
            time.sleep(POLL_INTERVAL)
    except Exception as e:
        print(f"Unexpected error: {e}")
        for sensor in sensors.values():
            sensor.close()
    finally:
        for sensor in sensors.values():
            sensor.close()

if __name__ == "__main__":
    main()
