import asyncio
import json
import logging
import os
import signal
import time
import psutil
import sounddevice as sd
import numpy as np
from gpiozero import LED
from gpiozero.exc import PinValidationError
from aiohttp import ClientSession, ClientError
from datetime import datetime
import threading
import sys

# Configuration
CONFIG_FILE = "config.json"
DEFAULT_CONFIG = {
    "audio": {
        "sample_rate": 16000,
        "channels": 1,
        "duration": 1,
        "threshold": 0.01
    },
    "keywords": ["hello", "world", "thanks"],
    "sentiment": {
        "positive_threshold": 0.5,
        "negative_threshold": -0.5
    },
    "alert": {
        "gpio_pin": 17
    },
    "heartbeat": {
        "interval": 60
    },
    "config_update": {
        "interval": 300
    },
    "logging": {
        "interval": 60
    }
}

# Initialize logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Global variables
config = None
audio_task = None
heartbeat_task = None
config_update_task = None
led = None
client_session = None
running = True

def load_config():
    global config
    try:
        with open(CONFIG_FILE, 'r') as f:
            config = json.load(f)
    except FileNotFoundError:
        logging.error(f"Config file {CONFIG_FILE} not found. Using default configuration.")
        config = DEFAULT_CONFIG
    except json.JSONDecodeError:
        logging.error(f"Invalid JSON in config file {CONFIG_FILE}. Using default configuration.")
        config = DEFAULT_CONFIG

def validate_config():
    if not config:
        return False
    if "audio" not in config or "keywords" not in config or "sentiment" not in config or "alert" not in config:
        return False
    if "sample_rate" not in config["audio"] or "channels" not in config["audio"] or "duration" not in config["audio"] or "threshold" not in config["audio"]:
        return False
    if not isinstance(config["audio"]["sample_rate"], int) or not isinstance(config["audio"]["channels"], int) or not isinstance(config["audio"]["duration"], (int, float)) or not isinstance(config["audio"]["threshold"], (int, float)):
        return False
    if "keywords" not in config or not isinstance(config["keywords"], list) or not all(isinstance(kw, str) for kw in config["keywords"]):
        return False
    if "sentiment" not in config or "positive_threshold" not in config["sentiment"] or "negative_threshold" not in config["sentiment"]:
        return False
    if not isinstance(config["sentiment"]["positive_threshold"], (int, float)) or not isinstance(config["sentiment"]["negative_threshold"], (int, float)):
        return False
    if "alert" not in config or "gpio_pin" not in config["alert"]:
        return False
    if not isinstance(config["alert"]["gpio_pin"], int):
        return False
    if "heartbeat" not in config or "interval" not in config["heartbeat"]:
        return False
    if not isinstance(config["heartbeat"]["interval"], int):
        return False
    if "config_update" not in config or "interval" not in config["config_update"]:
        return False
    if not isinstance(config["config_update"]["interval"], int):
        return False
    if "logging" not in config or "interval" not in config["logging"]:
        return False
    if not isinstance(config["logging"]["interval"], int):
        return False
    return True

def setup_gpio():
    global led
    try:
        led = LED(config["alert"]["gpio_pin"])
    except PinValidationError:
        logging.error(f"Invalid GPIO pin {config['alert']['gpio_pin']}. Using default GPIO 17.")
        led = LED(17)

def get_audio_data(duration):
    try:
        audio = sd.rec(int(duration * config["audio"]["sample_rate"]), samplerate=config["audio"]["sample_rate"], channels=config["audio"]["channels"], dtype='float32')
        sd.wait()
        return audio
    except sd.PortAudioError as e:
        logging.error(f"Audio device error: {e}")
        return None

def compute_rolling_average(audio_data, window_size=10):
    if audio_data is None or len(audio_data) < window_size:
        return 0.0
    window = audio_data[-window_size:]
    return np.mean(np.abs(window))

def check_sentiment(rolling_avg):
    if rolling_avg > config["sentiment"]["positive_threshold"]:
        return "positive"
    elif rolling_avg < config["sentiment"]["negative_threshold"]:
        return "negative"
    return "neutral"

def trigger_alert():
    if led is not None:
        led.on()
        logging.info("Alert triggered.")
    else:
        logging.warning("LED not initialized.")

def send_heartbeat():
    global client_session
    try:
        async def _send_heartbeat():
            nonlocal client_session
            async with client_session.post("https://your-cloud-endpoint.com/heartbeat", json={"timestamp": datetime.now().isoformat()}) as response:
                if response.status == 200:
                    logging.info("Heartbeat sent successfully.")
                else:
                    logging.error(f"Failed to send heartbeat: {response.status}")
        asyncio.run(_send_heartbeat())
    except Exception as e:
        logging.error(f"Error sending heartbeat: {e}")

def check_for_config_update():
    try:
        if os.path.exists(CONFIG_FILE):
            with open(CONFIG_FILE, 'r') as f:
                new_config = json.load(f)
            if new_config != config:
                logging.info("Configuration update detected. Reloading config.")
                global config
                config = new_config
                validate_config()
                setup_gpio()
                if audio_task is not None:
                    audio_task.cancel()
                if heartbeat_task is not None:
                    heartbeat_task.cancel()
                if config_update_task is not None:
                    config_update_task.cancel()
                asyncio.run(main())
        else:
            logging.warning("Config file not found. Using current config.")
    except Exception as e:
        logging.error(f"Error checking for config update: {e}")

def log_system_stats():
    try:
        cpu_percent = psutil.cpu_percent(interval=1)
        mem = psutil.virtual_memory()
        disk = psutil.disk_usage('/')
        logging.info(f"CPU: {cpu_percent}%, Memory: {mem.percent}%, Disk: {disk.percent}%")
    except Exception as e:
        logging.error(f"Error logging system stats: {e}")

def shutdown():
    global running
    running = False
    if led is not None:
        led.off()
    if audio_task is not None:
        audio_task.cancel()
    if heartbeat_task is not None:
        heartbeat_task.cancel()
    if config_update_task is not None:
        config_update_task.cancel()
    if client_session is not None:
        client_session.close()
    logging.info("Shutting down application.")

def signal_handler(sig, frame):
    logging.info("Shutting down due to signal.")
    shutdown()

def audio_capture():
    global running
    while running:
        audio_data = get_audio_data(config["audio"]["duration"])
        if audio_data is not None:
            rolling_avg = compute_rolling_average(audio_data)
            sentiment = check_sentiment(rolling_avg)
            if sentiment == "positive" and rolling_avg > config["sentiment"]["positive_threshold"]:
                trigger_alert()
            elif sentiment == "negative" and rolling_avg < config["sentiment"]["negative_threshold"]:
                trigger_alert()
        time.sleep(0.1)

async def main():
    global audio_task, heartbeat_task, config_update_task, client_session
    load_config()
    if not validate_config():
        logging.error("Invalid configuration. Using default configuration.")
        config = DEFAULT_CONFIG
    setup_gpio()
    try:
        client_session = ClientSession()
    except Exception as e:
        logging.error(f"Error initializing aiohttp session: {e}")
        return

    audio_task = asyncio.create_task(audio_capture())
    heartbeat_task = asyncio.create_task(asyncio.sleep(config["heartbeat"]["interval"]))
    config_update_task = asyncio.create_task(asyncio.sleep(config["config_update"]["interval"]))
    logging_task = asyncio.create_task(asyncio.sleep(config["logging"]["interval"]))

    while running:
        await asyncio.sleep(0.1)
        if not audio_task.done():
            audio_task = asyncio.create_task(audio_capture())
        if not heartbeat_task.done():
            await send_heartbeat()
            heartbeat_task = asyncio.create_task(asyncio.sleep(config["heartbeat"]["interval"]))
        if not config_update_task.done():
            await check_for_config_update()
            config_update_task = asyncio.create_task(asyncio.sleep(config["config_update"]["interval"]))
        if not logging_task.done():
            await log_system_stats()
            logging_task = asyncio.create_task(asyncio.sleep(config["logging"]["interval"]))

    await asyncio.gather(audio_task, heartbeat_task, config_update_task, logging_task)
    shutdown()

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        asyncio.run(main())
    except Exception as e:
        logging.error(f"Application error: {e}")
    finally:
        shutdown()

