import logging
import time
import signal
import sys
from datetime import datetime
from gpiozero import MotionSensor
from gpiozero.pins.mock import MockPinFactory
from typing import List

class CleanEnergyMonitor:
    def __init__(self, pin: int = 17, debounce_interval: float = 2.0, poll_samples: int = 10, poll_interval: float = 0.5):
        self.pin = pin
        self.debounce_interval = debounce_interval
        self.poll_samples = poll_samples
        self.poll_interval = poll_interval
        self.motion_sensor = None
        self.detection_events: List[datetime] = []
        self.logger = logging.getLogger(__name__)
        self.logger.setLevel(logging.INFO)
        self.setup_logger()

    def setup_logger(self):
        handler = logging.StreamHandler()
        formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
        handler.setFormatter(formatter)
        self.logger.addHandler(handler)

    def initialize_sensor(self):
        try:
            self.motion_sensor = MotionSensor(self.pin, pin_factory=MockPinFactory())
            self.logger.info(f"Motion sensor initialized on GPIO {self.pin}")
        except Exception as e:
            self.logger.error(f"Failed to initialize motion sensor: {e}")
            sys.exit(1)

    def detect_motion(self):
        try:
            if self.motion_sensor.motion_detected:
                self.logger.info("Motion detected!")
                self.detection_events.append(datetime.now())
                time.sleep(self.debounce_interval)
        except Exception as e:
            self.logger.error(f"Error during motion detection: {e}")
            sys.exit(1)

    def poll_sensor(self):
        try:
            for _ in range(self.poll_samples):
                self.detect_motion()
                time.sleep(self.poll_interval)
        except Exception as e:
            self.logger.error(f"Error during sensor polling: {e}")
            sys.exit(1)

    def get_occupancy_statistics(self) -> int:
        return len(self.detection_events)

    def print_summary_report(self):
        self.logger.info(f"Total motion detection events: {self.get_occupancy_statistics()}")
        self.logger.info("Detection timestamps:")
        for timestamp in self.detection_events:
            self.logger.info(f"  {timestamp}")

    def run(self):
        try:
            self.initialize_sensor()
            self.poll_sensor()
            self.print_summary_report()
        except KeyboardInterrupt:
            self.logger.info("Received keyboard interrupt, shutting down gracefully.")
        finally:
            if self.motion_sensor:
                self.motion_sensor.close()
                self.logger.info("Motion sensor closed.")
            sys.exit(0)

def signal_handler(sig, frame):
    sys.exit(0)

if __name__ == "__main__":
    monitor = CleanEnergyMonitor()
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    monitor.run()

