from gpiozero import DigitalOutputDevice
from signal import signal, SIGINT
import time

# GPIO pin configuration
GPIO_PIN = 17  # BCM numbering

def setup_gpio():
    """Initialize the GPIO pin for output."""
    try:
        return DigitalOutputDevice(GPIO_PIN)
    except Exception as e:
        print(f"Error initializing GPIO pin {GPIO_PIN}: {e}")
        raise

def pulse_gpio(pin, duration_high=0.1, duration_low=0.1):
    """Generate a repeating pulse on the given GPIO pin."""
    try:
        while True:
            pin.on()
            time.sleep(duration_high)
            pin.off()
            time.sleep(duration_low)
    except KeyboardInterrupt:
        print("\nPulse interrupted by user.")
    except Exception as e:
        print(f"Error during pulse generation: {e}")
        raise

def shutdown_gpio(pin):
    """Release the GPIO pin and clean up."""
    try:
        pin.close()
        print("GPIO pin released.")
    except Exception as e:
        print(f"Error releasing GPIO pin: {e}")

def signal_handler(sig, frame):
    """Handle shutdown signals gracefully."""
    print("\nShutting down...")
    shutdown_gpio(pin)
    exit(0)

if __name__ == "__main__":
    try:
        # Set up signal handling for graceful shutdown
        signal(SIGINT, signal_handler)

        # Initialize GPIO pin
        pin = setup_gpio()

        # Start the pulse loop
        pulse_gpio(pin)

    except Exception as e:
        print(f"Critical error: {e}")
    finally:
        # Ensure GPIO is released on all exit paths
        if 'pin' in locals():
            shutdown_gpio(pin)

