import pigpio
import threading
import signal
import sys
import time

class OutputPin:
    def __init__(self, pin_number, value_list, initial_value=0):
        self.pin_number = pin_number
        self.value_list = value_list
        self.current_value = initial_value
        self.pwm = None
        self.lock = threading.Lock()
        self.pi = self._connect_to_pi()
        self._validate_pin()
        self._validate_initial_value()
        self._setup_pin()

    def _connect_to_pi(self):
        try:
            pi = pigpio.pi()
            if not pi.connected:
                raise ConnectionError("Failed to connect to pigpio daemon.")
            return pi
        except Exception as e:
            print(f"Error connecting to pigpio: {e}")
            sys.exit(1)

    def _validate_pin(self):
        if not (1 <= self.pin_number <= 27):
            raise ValueError(f"Invalid GPIO pin number: {self.pin_number}. Must be between 1 and 27.")

    def _validate_initial_value(self):
        if self.current_value not in self.value_list:
            raise ValueError(f"Initial value {self.current_value} not in value list {self.value_list}.")

    def _setup_pin(self):
        self.pwm = self.pi.set_PWM_dutycycle(self.pin_number, 0)
        self.pi.set_mode(self.pin_number, pigpio.OUTPUT)
        self.set_value(self.current_value)

    def set_value(self, value):
        if value not in self.value_list:
            raise ValueError(f"Value {value} not in value list {self.value_list}.")
        with self.lock:
            self.current_value = value
            self.pi.set_PWM_dutycycle(self.pin_number, 0)
            if value == 1:
                self.pi.set_PWM_dutycycle(self.pin_number, 255)
            else:
                self.pi.set_PWM_dutycycle(self.pin_number, 0)

    def shutdown(self):
        if self.pwm is not None:
            self.pi.set_PWM_dutycycle(self.pin_number, 0)
            self.pi.set_mode(self.pin_number, pigpio.INPUT)
            self.pwm = None
            print(f"Pin {self.pin_number} shutdown complete.")

class TriggerPin(OutputPin):
    def __init__(self, pin_number, pulse_duration=100, pulse_high=True):
        super().__init__(pin_number, value_list=(0, 1), initial_value=0)
        self.pulse_duration = pulse_duration
        self.pulse_high = pulse_high
        self._setup_pulse()

    def _setup_pulse(self):
        self.pi.set_PWM_frequency(self.pin_number, 1000)

    def trigger(self):
        with self.lock:
            if self.current_value == 1:
                return
            self.set_value(1)
            if self.pulse_high:
                self.pi.set_PWM_dutycycle(self.pin_number, 255)
            else:
                self.pi.set_PWM_dutycycle(self.pin_number, 0)
            time.sleep(self.pulse_duration / 1000)
            self.set_value(0)

def signal_handler(sig, frame):
    print("\nShutting down...")
    example_output.shutdown()
    example_trigger.shutdown()
    sys.exit(0)

if __name__ == "__main__":
    example_output = OutputPin(21, (0, 1), initial_value=0)
    example_trigger = TriggerPin(20, pulse_duration=100, pulse_high=True)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        print("Press Ctrl+C to exit.")
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        signal_handler(None, None)

