import logging
import signal
import zmq
import time
from gpiozero import PWMOutputDevice, OutputDevice
from datetime import datetime
from typing import Callable, Optional

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class PIDHandler:
    def __init__(self, pwm: bool = True, host: str = 'tcp://localhost', port: int = 5555, callback: Callable = None):
        self.pwm = pwm
        self.host = host
        self.port = port
        self.callback = callback
        self.global_err_state = False
        self.last_msg = datetime.now()
        self.error_output = None
        self.context = None
        self.socket = None
        self.setup_gpio()
        self.setup_zmq()
        self.signal_handler()

    def setup_gpio(self):
        try:
            if self.pwm:
                # Physical pin 12 (BCM GPIO 18) for PWM
                self.error_output = PWMOutputDevice(12, frequency=1000)
            else:
                # Physical pin 10 (BCM GPIO 15) for digital output
                self.error_output = OutputDevice(10)
        except Exception as e:
            logging.error(f"Failed to initialize GPIO: {e}")
            self.cleanup()
            raise

    def setup_zmq(self):
        try:
            self.context = zmq.Context()
            self.socket = self.context.socket(zmq.SUB)
            self.socket.connect(f"{self.host}:{self.port}")
            self.socket.setsockopt(zmq.SUBSCRIBE, b'')
        except Exception as e:
            logging.error(f"Failed to initialize ZMQ: {e}")
            self.cleanup()
            raise

    def signal_handler(self):
        signal.signal(signal.SIGINT, self.cleanup)
        signal.signal(signal.SIGTERM, self.cleanup)

    def cleanup(self, *args):
        logging.info("Cleaning up resources...")
        if self.error_output:
            self.error_output.close()
        if self.socket:
            self.socket.close()
        if self.context:
            self.context.term()
        exit(0)

