import pigpio
import time
from typing import Optional

class OutputPinError(Exception):
    """Custom exception for OutputPin errors."""
    pass

class OutputPin:
    def __init__(self, pin_number: int, initial_value: int):
        """
        Initialize the OutputPin class.

        Args:
            pin_number (int): BCM GPIO pin number (0-31).
            initial_value (int): Initial value (0 or 1).

        Raises:
            OutputPinError: If pin number or initial_value is invalid.
        """
        if not (0 <= pin_number <= 31):
            raise OutputPinError("Invalid pin number. Must be between 0 and 31.")
        if initial_value not in (0, 1):
            raise OutputPinError("Initial value must be 0 or 1.")

        self.pin_number = pin_number
        self.initial_value = initial_value
        self.pi = None
        self._connected = False

        try:
            self.pi = pigpio.pi()
            if not self.pi.connected:
                raise OutputPinError("Failed to connect to pigpio daemon.")
            self._connected = True
            self._setup_pin()
            self.set_value(initial_value)
        except Exception as e:
            self.shutdown()
            raise OutputPinError(f"Initialization failed: {e}")

    def _setup_pin(self):
        """Set the pin mode to output."""
        try:
            self.pi.set_mode(self.pin_number, pigpio.OUTPUT)
        except Exception as e:
            raise OutputPinError(f"Failed to set pin mode: {e}")

    def set_value(self, value: int):
        """
        Set the value of the pin.

        Args:
            value (int): Value to set (0 or 1).

        Raises:
            OutputPinError: If value is invalid.
        """
        if value not in (0, 1):
            raise OutputPinError("Value must be 0 or 1.")

        try:
            self.pi.write(self.pin_number, value)
        except Exception as e:
            raise OutputPinError(f"Failed to write to pin: {e}")

    def shutdown(self):
        """Cleanly shut down the pigpio connection."""
        try:
            if self._connected:
                self.pi.set_mode(self.pin_number, pigpio.INPUT)
                self.pi.stop()
                self._connected = False
        except Exception as e:
            raise OutputPinError(f"Shutdown failed: {e}")

    def __del__(self):
        """Ensure shutdown is called on deletion."""
        try:
            self.shutdown()
        except Exception as e:
            print(f"Error during cleanup: {e}")

if __name__ == '__main__':
    try:
        pin = OutputPin(17, 0)
        print("Starting GPIO 17 toggle...")
        for _ in range(10):
            pin.set_value(1)
            time.sleep(0.5)
            pin.set_value(0)
            time.sleep(0.5)
        print("Shutting down...")
        pin.shutdown()
    except OutputPinError as e:
        print(f"Error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")

