from gpiozero.pins.pigpio import PiGPIOFactory
from threading import Thread

# Initialize GPIO using PiGPIO for hardware PWM support, fallback to software if not available
try:
    pin_factory = PiGPIOFactory()
except:
    pin_factory = None

# GPIO pin for the fan (BCM 12)
FAN_PIN = 12
# Standard PWM frequency for 4-wire fans
PWM_FREQUENCY = 25000

# Initialize PWM device
try:
    fan = PWMOutputDevice(FAN_PIN, pin_factory=pin_factory, frequency=PWM_FREQUENCY)
