    print(f"Failed to initialize PWM device: {e}")
    print("Falling back to software PWM...")
    fan = PWMOutputDevice(FAN_PIN, pin_factory=None, frequency=PWM_FREQUENCY)

# Set initial duty cycle to 0%
fan.value = 0.0

def signal_handler(sig, frame):
    print("\nShutting down fan control...")
    fan.value = 0.0
    fan.close()
    sys.exit(0)

def input_thread():
    while True:
        try:
            user_input = input("Enter fan speed (0-100) or 'q' to quit: ").strip()
            if user_input.lower() == 'q':
                signal_handler(None, None)
                break
            speed = float(user_input)
            if 0 <= speed <= 100:
                fan.value = speed / 100.0
            else:
                print("Invalid input. Please enter a value between 0 and 100.")
        except ValueError:
            print("Invalid input. Please enter a number or 'q' to quit.")

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    print("Fan control started. Enter a speed (0-100) or 'q' to quit.")

    try:
        input_thread()
    except KeyboardInterrupt:
        signal_handler(None, None)

if __name__ == "__main__":
