import signal
import time
from gpiozero import LED
from gpiozero.exc import PinInvalidError
import sys

class LEDController:
    def __init__(self, pin_number):
        try:
            self.led = LED(pin_number)
        except PinInvalidError as e:
            raise ValueError(f"Invalid GPIO pin: {e}") from e
        except Exception as e:
            raise ValueError(f"Error initializing LED: {e}") from e

    def on(self):
        try:
            self.led.on()
        except Exception as e:
            print(f"Error turning LED on: {e}")
            raise

    def off(self):
        try:
            self.led.off()
        except Exception as e:
            print(f"Error turning LED off: {e}")
            raise

    def blink(self, on_duration, off_duration):
        if on_duration < 0 or off_duration < 0:
            raise ValueError("Duration must be non-negative")
        try:
            self.on()
            time.sleep(on_duration)
            self.off()
            time.sleep(off_duration)
        except Exception as e:
            print(f"Error during blink: {e}")
            raise

def signal_handler(sig, frame):
    print("\nCtrl+C or termination signal received. Turning off LED and exiting.")
    try:
        if hasattr(signal_handler, 'controller'):
            signal_handler.controller.off()
    except Exception as e:
        print(f"Error during cleanup: {e}")
    sys.exit(0)

def main():
    pin_number = 25  # Physical pin 22 corresponds to GPIO 25
    try:
        controller = LEDController(pin_number)
        signal.signal(signal.SIGINT, signal_handler)
        signal.signal(signal.SIGTERM, signal_handler)
        signal_handler.controller = controller
        print("LEDController initialized. Starting blink loop...")
        while True:
            try:
                controller.blink(1.0, 0.5)
            except ValueError as e:
                print(f"Runtime error: {e}")
                break
            except Exception as e:
                print(f"Unexpected error: {e}")
                break
    except ValueError as e:
        print(f"Initialization error: {e}")
    except Exception as e:
        print(f"Unexpected error during setup: {e}")
    finally:
        try:
            if hasattr(signal_handler, 'controller'):
                signal_handler.controller.off()
        except Exception as e:
            print(f"Error during final cleanup: {e}")

if __name__ == "__main__":
    main()

