# Mapping for digit to duty cycle
digit_to_duty_cycle = {0: 0, 1: 20, 2: 40, 3: 60, 4: 80, 5: 100, 6: 80, 7: 20, 8: 100, 9: 80}

def digit_to_duty_cycle_func(digit):
    return digit_to_duty_cycle.get(digit, 0)

def format_price(price):
    if price < 0 or price > 99.99:
        return "Err"
    return f"{price:.2f}"

def display_price(price, gpio_pins, frequency, duty_cycle, display_time, simulate):
    try:
        formatted_price = format_price(price)
        if formatted_price == "Err":
            for pin in gpio_pins:
                if not simulate:
                    pwm = GPIO.PWM(pin, frequency)
                    pwm.start(0)
                    time.sleep(0.1)
                    pwm.stop()
                else:
                    print(f"Pin {pin}: Duty Cycle 0")
            return

        digits = list(formatted_price)
        if len(digits) != 4:
            digits = [' '] * 4
        else:
            digits[2] = ' '  # Replace decimal point with space

        for i, digit in enumerate(digits):
            if digit not in digit_to_duty_cycle:
                digit = '0'
            duty = digit_to_duty_cycle[digit]
            pin = gpio_pins[i]
            if not simulate:
                pwm = GPIO.PWM(pin, frequency)
                pwm.start(duty)
                time.sleep(display_time)
                pwm.stop()
            else:
                print(f"Pin {pin}: Duty Cycle {duty}")
    except Exception as e:
        logging.error(f"Error in display_price: {str(e)}")
        raise

def signal_handler(sig, frame):
    print("Cleaning up GPIO...")
    GPIO.cleanup()
    sys.exit(0)

