    """Transcribe energy level to a keyword based on modulo 3."""
    keyword_map = {0: 'water', 1: 'stop', 2: 'status'}
    return keyword_map[energy % 3]

def map_to_farm_action(keyword):
    """Map keyword to corresponding farm action."""
    action_map = {
        'water': 'open_valve',
        'stop': 'close_valve',
        'status': 'report'
    }
    return action_map.get(keyword, 'unknown')

