import requests
from gpiozero import Button
from signal import signal, SIGINT

# Configuration
BUTTON_PIN = 17
PART_ID = 'PART-204'
URL = 'http://localhost:8000/quality'
CHECK_INTERVAL = 2  # seconds

# Initialize button with internal pull-up and active-low
button = Button(BUTTON_PIN, pull_up=True)

def create_report():
    """Create a JSON report based on the button state."""
    if button.is_pressed:
        return {
            "part_id": PART_ID,
            "passed": False,
            "defect_count": 1
        }
    else:
        return {
            "part_id": PART_ID,
            "passed": True,
            "defect_count": 0
        }

def send_report(report):
    """Send the report via HTTP POST and handle errors."""
    try:
        response = requests.post(URL, json=report, timeout=5)
        print(f"Report submitted. Status code: {response.status_code}")
        return response.status_code
    except requests.exceptions.RequestException as e:
        print(f"Network error: {e}")
        return None

def signal_handler(sig, frame):
    """Handle keyboard interrupt and clean up GPIO."""
    print("\nCleaning up and exiting...")
    button.close()
    exit(0)

def main():
    # Set up signal handler for clean exit
    signal(SIGINT, signal_handler)

    try:
        while True:
            report = create_report()
            status_code = send_report(report)
            if status_code is not None and status_code == 200:
                print("Report successfully submitted.")
            time.sleep(CHECK_INTERVAL)
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        button.close()

if __name__ == "__main__":
    main()

