import RPi.GPIO as GPIO
import time
import signal
import logging
import sys

# Configuration
GPIO_PIN = 17
MAX_DURATION = 0.5
DEFAULT_PATTERN_DURATION = 0.2
DEBOUNCE_DELAY = 0.01
LOG_FILE = 'speaker_control.log'

# Setup logging
logging.basicConfig(filename=LOG_FILE, level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Initialize GPIO
def setup_gpio():
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(GPIO_PIN, GPIO.OUT, initial=GPIO.LOW)
        logging.info("GPIO initialized successfully.")
        return True
    except Exception as e:
        logging.error(f"Failed to initialize GPIO: {e}")
        return False

# Deactivate the actuator
def deactivate_actuator():
    try:
        GPIO.output(GPIO_PIN, GPIO.LOW)
        logging.info("Actuator deactivated.")
    except Exception as e:
        logging.error(f"Error deactivating actuator: {e}")

# Activate the actuator for a given duration
def activate_actuator(duration):
    try:
        duration = min(duration, MAX_DURATION)
        GPIO.output(GPIO_PIN, GPIO.HIGH)
        time.sleep(duration)
        GPIO.output(GPIO_PIN, GPIO.LOW)
        time.sleep(DEBOUNCE_DELAY)
        logging.info(f"Actuator activated for {duration:.2f} seconds.")
    except Exception as e:
        logging.error(f"Error activating actuator: {e}")

# Play default pattern
def play_default_pattern():
    try:
        activate_actuator(DEFAULT_PATTERN_DURATION)
    except Exception as e:
        logging.error(f"Error playing default pattern: {e}")

# Process command
def process_command(command):
    try:
        if command == "TRIGGER":
            play_default_pattern()
        else:
            logging.warning(f"Unknown command: {command}")
    except Exception as e:
        logging.error(f"Error processing command: {e}")

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    logging.info("Received signal to shutdown.")
    deactivate_actuator()
    GPIO.cleanup()
    sys.exit(0)

# Main loop
def main():
    if not setup_gpio():
        sys.exit(1)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        while True:
            process_command("TRIGGER")
            time.sleep(5)
    except Exception as e:
        logging.error(f"Main loop error: {e}")
    finally:
        deactivate_actuator()
        GPIO.cleanup()

if __name__ == "__main__":
    main()

