import time
import threading

class MotorError(Exception):
    pass

class Motor:
    def __init__(self, pi: pigpio.pi, pin: int):
        self.pi = pi
        self.pin = pin
        self._lock = threading.Lock()
        self._is_connected = False

        if not pi:
            raise MotorError("Invalid or disconnected pigpio instance")

        try:
            self.pi.set_mode(self.pin, pigpio.OUTPUT)
            self._is_connected = True
            self.set_frequency(1000)
            self.set_duty_cycle(0)
        except Exception as e:
            self._is_connected = False
            raise MotorError(f"Failed to initialize motor: {e}")

    def set_frequency(self, freq: int):
        if not self._is_connected:
            raise MotorError("Motor is not connected or pigpio instance is invalid")

        if freq <= 0:
            raise MotorError("Frequency must be a positive integer")

        try:
            self.pi.set_PWM_frequency(self.pin, freq)
        except Exception as e:
            raise MotorError(f"Failed to set frequency: {e}")

    def set_duty_cycle(self, duty: int):
        if not self._is_connected:
            raise MotorError("Motor is not connected or pigpio instance is invalid")

        if not isinstance(duty, int) or not (0 <= duty <= 255):
            raise MotorError("Duty cycle must be an integer between 0 and 255")

        try:
            self.pi.set_PWM_dutycycle(self.pin, duty)
        except Exception as e:
            raise MotorError(f"Failed to set duty cycle: {e}")

    def stop(self):
        if self._is_connected:
            self.set_duty_cycle(0)

    def __del__(self):
        self.stop()
        if self._is_connected:
            try:
                self.pi.stop()
            except:
                pass

    def close(self):
        self.stop()
        if self._is_connected:
            try:
                self.pi.stop()
            except:
                pass
            self._is_connected = False

