import RPi.GPIO as GPIO
import logging
import time
import signal
import sys

# Setup logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class ServoController:
    def __init__(self, pin):
        self.pin = pin
        self.pwm = None
        self.running = False
        self.setup_gpio()

    def setup_gpio(self):
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.pin, GPIO.OUT)
            self.pwm = GPIO.PWM(self.pin, 50)  # 50 Hz PWM frequency
            self.pwm.start(0)
            logging.info(f"Servo initialized on GPIO {self.pin}")
        except Exception as e:
            logging.error(f"Failed to initialize servo: {e}")
            raise

    def _angle_to_duty_cycle(self, angle):
        if not (0 <= angle <= 180):
            raise ValueError("Angle must be between 0 and 180 degrees")
        return 2.5 + (12.5 - 2.5) * (angle / 180)

    def move_to(self, angle):
        try:
            duty_cycle = self._angle_to_duty_cycle(angle)
            self.pwm.ChangeDutyCycle(duty_cycle)
            logging.info(f"Moving servo to {angle} degrees (duty cycle: {duty_cycle:.2f}%)")
        except Exception as e:
            logging.error(f"Error moving servo to {angle} degrees: {e}")

    def stop(self):
        if self.pwm:
            self.pwm.stop()
            self.pwm = None
            logging.info("Servo stopped")
        GPIO.cleanup()
        logging.info("GPIO cleaned up")

    def __del__(self):
        self.stop()

def signal_handler(sig, frame):
    logging.info("Interrupt received. Stopping servo and cleaning up.")
    try:
        if hasattr(signal_handler, 'servo'):
            signal_handler.servo.stop()
    except Exception as e:
        logging.error(f"Error during cleanup: {e}")
    sys.exit(0)

def main(angles):
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    signal_handler.servo = ServoController(18)
    try:
        for angle in angles:
            signal_handler.servo.move_to(angle)
            time.sleep(0.5)
        # Sweep back down
        for angle in reversed(angles):
            if angle != 0:
                signal_handler.servo.move_to(angle)
                time.sleep(0.5)
    except Exception as e:
        logging.error(f"Main loop error: {e}")
    finally:
        signal_handler.servo.stop()

if __name__ == "__main__":
    angles = [0, 45, 90, 135, 180]
    main(angles)

