import logging
import signal
import sys
import time
import automationhat
from automationhat import relay, input

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Global variables
garage_door = None
state_pin = 1
relay_pin = 1
exit_code = 0

def log_and_exit(message, exit_code=0):
    logging.error(message)
    sys.exit(exit_code)

def check_automationhat_installed():
    try:
        import automationhat
        return True
    except ImportError:
        log_and_exit("Automation HAT library not installed. Exiting.", 0)
        return False

def check_hardware_present():
    try:
        # Check if the input channel is available
        input.channel(1)
        # Check if the relay is available
        relay.one
        return True
    except Exception as e:
        log_and_exit(f"Hardware not present or not accessible: {e}", 0)
        return False

def safe_exit(signum, frame):
    global exit_code
    logging.info("Shutting down gracefully...")
    if garage_door:
        garage_door.turn_off()
    sys.exit(exit_code)

def trigger_relay(duration=0.5):
    try:
        relay.one.on()
        time.sleep(duration)
        relay.one.off()
    except Exception as e:
        logging.error(f"Error triggering relay: {e}")

def read_state():
    try:
        state = input.channel(state_pin).value
        if state is None:
            logging.warning("Received None from state pin. Assuming door is open.")
            return 0
        if state not in (0, 1):
            logging.warning(f"Unexpected state value: {state}. Assuming door is open.")
            return 0
        return state
    except Exception as e:
        logging.error(f"Error reading state pin: {e}")
        return 0

class GarageDoor:
    def __init__(self, state_pin):
        self.state_pin = state_pin
        self._state = 0
        self._last_state = 0
        self._running = True

        try:
            self._state = read_state()
            self._last_state = self._state
        except Exception as e:
            logging.error(f"Error initializing state: {e}")
            self._state = 0

    @property
    def state(self):
        return self._state

    def turn_off(self):
        try:
            relay.one.off()
        except Exception as e:
            logging.error(f"Error turning off relay: {e}")

    def toggle(self):
        try:
            self._state = read_state()
            if self._state == 1:
                logging.info("Door is closed. Opening...")
                trigger_relay()
            else:
                logging.info("Door is open. Closing...")
                trigger_relay()
            self._last_state = self._state
        except Exception as e:
            logging.error(f"Error toggling door: {e}")

def main():
    global garage_door, exit_code

    if not check_automationhat_installed():
        return

    if not check_hardware_present():
        return

    signal.signal(signal.SIGINT, safe_exit)
    signal.signal(signal.SIGTERM, safe_exit)

    try:
        garage_door = GarageDoor(state_pin)
        logging.info("Garage door controller initialized.")

        while garage_door._running:
            current_state = garage_door.state
            if current_state != garage_door._last_state:
                garage_door.toggle()
                garage_door._last_state = current_state
            time.sleep(1)
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
        exit_code = 1
    finally:
        if garage_door:
            garage_door.turn_off()
        sys.exit(exit_code)

if __name__ == "__main__":
    main()

