import serial
import minimalmodbus
import signal
import sys
import logging
import time
import os

# Set up logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class ModbusServoController:
    def __init__(self, port='/dev/serial0', baudrate=115200, slave_address=1):
        self.port = port
        self.baudrate = baudrate
        self.slave_address = slave_address
        self.serial_port = None
        self.modbus = None
        self.running = False
        self.signal_received = False

        # Register addresses
        self.REGISTER_OPERATION_MODE = 0x3500
        self.REGISTER_POSITION_COMMAND = 0x4000
        self.REGISTER_VELOCITY_COMMAND = 0x6F00
        self.REGISTER_POSITION_FEEDBACK = 0x3700
        self.REGISTER_VELOCITY_FEEDBACK = 0x3B00
        self.REGISTER_START = 0x3100
        self.REGISTER_STOP = 0x3100
        self.REGISTER_STATUS = 0x3000

        # Register values
        self.START_COMMAND = 0x000F
        self.STOP_COMMAND = 0x0006

    def _setup_modbus(self):
        try:
            self.serial_port = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=8,
                parity='N',
                stopbits=1,
                timeout=1
            )
            self.modbus = minimalmodbus.Instrument(self.serial_port, self.slave_address)
            self.modbus.serial.timeout = 1
            self.modbus.mode = minimalmodbus.MODE_RTU
            logging.info(f"Modbus RTU initialized on {self.port} with slave address {self.slave_address}")
        except serial.SerialException as e:
            logging.error(f"Failed to open serial port {self.port}: {e}")
            raise
        except Exception as e:
            logging.error(f"Unexpected error initializing Modbus: {e}")
            raise

    def _teardown_modbus(self):
        if self.modbus:
            try:
                self.modbus.close()
            except Exception as e:
                logging.error(f"Error closing Modbus: {e}")
        if self.serial_port:
            try:
                self.serial_port.close()
            except Exception as e:
                logging.error(f"Error closing serial port: {e}")

    def _handle_signal(self, signum, frame):
        self.signal_received = True
        self.running = False

    def set_operation_mode(self, mode):
        if not isinstance(mode, int) or mode < 0 or mode > 65535:
            raise ValueError("Operation mode must be an integer between 0 and 65535")
        try:
            self.modbus.write_register(self.REGISTER_OPERATION_MODE, mode, functioncode=6)
            logging.info(f"Set operation mode to {mode}")
        except minimalmodbus.ModbusException as e:
            logging.error(f"Modbus error setting operation mode: {e}")
            raise
        except Exception as e:
            logging.error(f"Unexpected error setting operation mode: {e}")
            raise

    def write_position_command(self, value):
        if not isinstance(value, int) or value < 0 or value > 65535:
            raise ValueError("Position command must be an integer between 0 and 65535")
        try:
            self.modbus.write_register(self.REGISTER_POSITION_COMMAND, value, functioncode=6)
            logging.info(f"Set position command to {value}")
        except minimalmodbus.ModbusException as e:
            logging.error(f"Modbus error writing position command: {e}")
            raise
        except Exception as e:
            logging.error(f"Unexpected error writing position command: {e}")
            raise

    def write_velocity_command(self, value):
        if not isinstance(value, int) or value < -32768 or value > 32767:
            raise ValueError("Velocity command must be an integer between -32768 and 32767")
        try:
            self.modbus.write_register(self.REGISTER_VELOCITY_COMMAND, value, functioncode=6)
            logging.info(f"Set velocity command to {value}")
        except minimalmodbus.ModbusException as e:
            logging.error(f"Modbus error writing velocity command: {e}")
            raise
        except Exception as e:
            logging.error(f"Unexpected error writing velocity command: {e}")
            raise

    def read_position_feedback(self):
        try:
            value = self.modbus.read_register(self.REGISTER_POSITION_FEEDBACK, functioncode=3)
            logging.info(f"Read position feedback: {value}")
            return value
        except minimalmodbus.ModbusException as e:
            logging.error(f"Modbus error reading position feedback: {e}")
            raise
        except Exception as e:
            logging.error(f"Unexpected error reading position feedback: {e}")
            raise

    def read_velocity_feedback(self):
        try:
            value = self.modbus.read_register(self.REGISTER_VELOCITY_FEEDBACK, functioncode=3)
            logging.info(f"Read velocity feedback: {value}")
            return value
        except minimalmodbus.ModbusException as e:
            logging.error(f"Modbus error reading velocity feedback: {e}")
            raise
        except Exception as e:
            logging.error(f"Unexpected error reading velocity feedback: {e}")
            raise

    def start(self):
        try:
            self.modbus.write_register(self.REGISTER_START, self.START_COMMAND, functioncode=6)
            logging.info("Started servo motor")
        except minimalmodbus.ModbusException as e:
            logging.error(f"Modbus error starting servo: {e}")
            raise
        except Exception as e:
            logging.error(f"Unexpected error starting servo: {e}")
            raise

    def stop(self):
        try:
            self.modbus.write_register(self.REGISTER_STOP, self.STOP_COMMAND, functioncode=6)
            logging.info("Stopped servo motor")
        except minimalmodbus.ModbusException as e:
            logging.error(f"Modbus error stopping servo: {e}")
            raise
        except Exception as e:
            logging.error(f"Unexpected error stopping servo: {e}")
            raise

    def read_status(self):
        try:
            value = self.modbus.read_register(self.REGISTER_STATUS, functioncode=3)
            logging.info(f"Read status: {value}")
            return value
        except minimalmodbus.ModbusException as e:
            logging.error(f"Modbus error reading status: {e}")
            raise
        except Exception as e:
            logging.error(f"Unexpected error reading status: {e}")
            raise

    def run(self):
        self.running = True
        signal.signal(signal.SIGINT, self._handle_signal)
        signal.signal(signal.SIGTERM, self._handle_signal)

        try:
            while self.running:
                time.sleep(0.1)
        except KeyboardInterrupt:
            logging.info("Received SIGINT, shutting down...")
        finally:
            self.stop()
            self._teardown_modbus()
            logging.info("Servo controller shut down cleanly.")

def main():
    try:
        controller = ModbusServoController()
        controller._setup_modbus()
        controller.run()
    except serial.SerialException as e:
        logging.error(f"Serial port {controller.port} not available. Exiting with code 0.")
        sys.exit(0)
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
        sys.exit(1)

if __name__ == '__main__':
    main()

