import os
import time
import logging
import threading
import serial
import RPi.GPIO as GPIO
from gpiozero import Button
from datetime import datetime

# Configuration
SERIAL_PORT = '/dev/ttyUSB0'
SERIAL_BAUD = 9600
BUTTON_PIN = 2  # BCM
SOLENOID_PIN = 17
THRESHOLD = 0.25  # grams
MAX_SOLENOID_DURATION = 1.0  # seconds
BUTTON_DEBOUNCE_DELAY = 0.2  # seconds
LOG_FILE = 'seed_sorter.log'

# Setup logging
logging.basicConfig(
    filename=LOG_FILE,
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Initialize GPIO
GPIO.setmode(GPIO.BCM)
GPIO.setwarnings(False)

# Initialize serial port
try:
    serial_port = serial.Serial(SERIAL_PORT, SERIAL_BAUD, timeout=1)
except serial.SerialException as e:
    logging.error(f"Failed to open serial port: {e}")
    exit(1)

# Initialize solenoid control
solenoid_active = False
solenoid_start_time = 0
solenoid_duration = 0

# Button press event
button = Button(BUTTON_PIN, pull_up=True)
button.when_pressed = button_pressed

def button_pressed():
    global solenoid_active, solenoid_start_time, solenoid_duration
    logging.info("Button pressed")
    try:
        # Read weight from serial
        weight = read_weight()
        if weight is not None:
            logging.info(f"Weight: {weight} grams")
            if weight > THRESHOLD:
                if not solenoid_active:
                    solenoid_active = True
                    solenoid_start_time = time.time()
                    logging.info("Solenoid activated")
                    activate_solenoid()
                else:
                    logging.warning("Solenoid already active")
            else:
                logging.info("Weight below threshold")
        else:
            logging.warning("Invalid weight data")
    except Exception as e:
        logging.error(f"Error during button press: {e}")

def read_weight():
    try:
        line = serial_port.readline().decode('utf-8').strip()
        if line:
            try:
                weight = float(line)
                return weight
            except ValueError:
                logging.error("Invalid weight data format")
                return None
    except serial.SerialException as e:
        logging.error(f"Serial communication error: {e}")
        return None

def activate_solenoid():
    global solenoid_active, solenoid_start_time, solenoid_duration
    try:
        GPIO.output(SOLENOID_PIN, GPIO.HIGH)
        solenoid_active = True
        solenoid_start_time = time.time()
        logging.info("Solenoid activated")
    except Exception as e:
        logging.error(f"Error activating solenoid: {e}")

def deactivate_solenoid():
    global solenoid_active, solenoid_duration
    try:
        GPIO.output(SOLENOID_PIN, GPIO.LOW)
        solenoid_active = False
        solenoid_duration = time.time() - solenoid_start_time
        logging.info(f"Solenoid deactivated after {solenoid_duration:.2f} seconds")
    except Exception as e:
        logging.error(f"Error deactivating solenoid: {e}")

def solenoid_timer():
    global solenoid_active, solenoid_duration
    while True:
        if solenoid_active:
            current_time = time.time()
            solenoid_duration = current_time - solenoid_start_time
            if solenoid_duration >= MAX_SOLENOID_DURATION:
                logging.error("Solenoid duration exceeded safety limit")
                deactivate_solenoid()
        time.sleep(0.1)

def serial_reader():
    global solenoid_active
    while True:
        try:
            weight = read_weight()
            if weight is not None:
                logging.info(f"Weight reading: {weight} grams")
        except Exception as e:
            logging.error(f"Serial reader error: {e}")
        time.sleep(0.1)

def cleanup():
    global solenoid_active
    logging.info("Cleaning up resources")
    try:
        if solenoid_active:
            deactivate_solenoid()
        serial_port.close()
        GPIO.cleanup()
    except Exception as e:
        logging.error(f"Cleanup error: {e}")

def main():
    try:
        # Start solenoid timer thread
        solenoid_thread = threading.Thread(target=solenoid_timer, daemon=True)
        solenoid_thread.start()

        # Start serial reader thread
        serial_thread = threading.Thread(target=serial_reader, daemon=True)
        serial_thread.start()

        # Wait for user input
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt received")
        cleanup()
        exit(0)

if __name__ == "__main__":
    try:
        # Initialize solenoid pin
        GPIO.setup(SOLENOID_PIN, GPIO.OUT)
        main()
    except Exception as e:
        logging.error(f"Initialization error: {e}")
        cleanup()
        exit(1)

