import smbus2
import time
import signal
import sys

# I2C bus and sensor address
I2C_BUS = 1
SENSOR_ADDR = 0x5A
APP_START_REG = 0xF4
ALG_RESULT_DATA_REG = 0x02

# Initialize I2C bus
try:
    bus = smbus2.SMBus(I2C_BUS)
except OSError as e:
    print(f"Error initializing I2C bus: {e}")
    sys.exit(1)

def verify_sensor_presence():
    """Check if the sensor is present by reading the WHO_AM_I register."""
    try:
        who_am_i = bus.read_byte_data(SENSOR_ADDR, 0x00)
        if who_am_i == 0x81:
            print("Sensor detected.")
            return True
        else:
            print(f"Unexpected WHO_AM_I value: 0x{who_am_i:02X}. Sensor not found.")
            return False
    except (OSError, IOError) as e:
        print(f"Error checking sensor presence: {e}")
        return False

def initialize_sensor():
    """Initialize the sensor by writing to the APP_START register."""
    try:
        bus.write_byte_data(SENSOR_ADDR, APP_START_REG, 0x20)
        print("Sensor initialized.")
    except (OSError, IOError) as e:
        print(f"Error initializing sensor: {e}")
        sys.exit(1)

def read_co2_concentration():
    """Read CO2 concentration from the ALG_RESULT_DATA register."""
    try:
        high_byte = bus.read_byte_data(SENSOR_ADDR, ALG_RESULT_DATA_REG)
        low_byte = bus.read_byte_data(SENSOR_ADDR, ALG_RESULT_DATA_REG + 1)
        co2 = (high_byte << 8) | low_byte
        return co2
    except (OSError, IOError) as e:
        print(f"Error reading CO2 data: {e}")
        return None

def signal_handler(sig, frame):
    """Handle keyboard interrupts and clean up."""
    print("\nCtrl+C detected. Exiting gracefully.")
    try:
        bus.close()
    except:
        pass
    sys.exit(0)

def main():
    if not verify_sensor_presence():
        sys.exit(1)

    initialize_sensor()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        for _ in range(5):
            co2 = read_co2_concentration()
            if co2 is not None:
                print(f"CO2 concentration: {co2} ppm")
            else:
                print("Failed to read CO2 data.")
            time.sleep(2)
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        try:
            bus.close()
        except:
            pass

if __name__ == "__main__":
    main()

