import serial
import time
import logging
import signal
import sys
from datetime import datetime

# Configure logging
log_file = 'co2_readings_log.txt'
logging.basicConfig(filename=log_file, level=logging.INFO, format='%(asctime)s - %(message)s')

# Global flag to control the loop
running = True

def signal_handler(sig, frame):
    global running
    print("\nShutting down gracefully...")
    running = False

def setup_logger():
    try:
        # Ensure log file is writable
        with open(log_file, 'a'):
            pass
    except IOError as e:
        print(f"Failed to open log file: {e}")
        sys.exit(1)

def read_co2():
    try:
        # Open serial port
        ser = serial.Serial(
            port='/dev/ttyUSB0',
            baudrate=9600,
            timeout=1
        )
        print("Serial port opened successfully.")
    except serial.SerialException as e:
        print(f"Serial port error: {e}")
        return None

    try:
        # Read one line from the serial port
        line = ser.readline().decode('ascii', errors='replace').strip()
        print(f"Received CO2 data: {line}")
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        line = None
    finally:
        try:
            ser.close()
        except serial.SerialException as e:
            print(f"Error closing serial port: {e}")

    return line

def log_co2_data(co2_value):
    if co2_value and co2_value.isdigit():
        try:
            ppm = int(co2_value)
            timestamp = datetime.now().isoformat()
            log_entry = f"{timestamp} - {ppm} ppm\n"
            logging.info(log_entry)
            print(f"Logged CO2: {ppm} ppm")
        except ValueError as e:
            print(f"Error converting CO2 value to integer: {e}")
    else:
        print("Invalid or empty CO2 data, skipping log.")

def main():
    global running
    setup_logger()
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    while running:
        try:
            co2_line = read_co2()
            if co2_line:
                log_co2_data(co2_line)
            else:
                print("No data received from CO2 sensor.")
            time.sleep(5)
        except ValueError as e:
            print(f"ValueError in main loop: {e}")
