import serial
import time
import signal
import sys
import threading
from typing import Optional, Any, Dict, List

class ESP8266Communicator:
    def __init__(self, port: str = '/dev/ttyS0', baudrate: int = 115200, timeout: int = 5, rx_buffer_size: int = 1024, tx_buffer_size: int = 1024):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.rx_buffer_size = rx_buffer_size
        self.tx_buffer_size = tx_buffer_size
        self.serial_port = None
        self.lock = threading.Lock()
        self.signal_received = False
        self.signal_handler = None

        # Set up signal handling for clean exit
        signal.signal(signal.SIGINT, self.signal_handler)
        signal.signal(signal.SIGTERM, self.signal_handler)

    def signal_handler(self, sig, frame):
        self.signal_received = True
        self.cleanup()

    def cleanup(self):
        if self.signal_received:
            print("Shutting down ESP8266Communicator...")
            self.close()
            sys.exit(0)

    def open(self):
        """Open the serial port with specified parameters."""
        try:
            self.serial_port = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                timeout=self.timeout,
                write_timeout=self.timeout,
                rtscts=False,
                dsrdtr=False,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                xonxoff=False,
                timeout=self.timeout,
                write_buffer_size=self.tx_buffer_size,
                read_buffer_size=self.rx_buffer_size
            )
            print(f"Serial port {self.port} opened successfully.")
        except serial.SerialException as e:
            print(f"Error opening serial port {self.port}: {e}")
            self.serial_port = None
            raise

    def close(self):
        """Close the serial port."""
        if self.serial_port and self.serial_port.is_open:
            try:
                self.serial_port.close()
                print(f"Serial port {self.port} closed.")
            except serial.SerialException as e:
                print(f"Error closing serial port {self.port}: {e}")

    def _send_command(self, command: str, delay: int = 1, max_retries: int = 3) -> bool:
        """Send an AT command and wait for a response, retrying up to max_retries times."""
        if not self.serial_port or not self.serial_port.is_open:
            raise RuntimeError("Serial port not open.")

        for attempt in range(max_retries):
            try:
                with self.lock:
                    self.serial_port.write((command + '\r\n').encode())
                    time.sleep(delay)
                    response = self._read_response()
                if response:
                    return True
                else:
                    print(f"Attempt {attempt + 1} failed. Retrying...")
                    time.sleep(0.5)
            except serial.SerialException as e:
                print(f"Serial error during command send: {e}")
                time.sleep(0.5)
        return False

    def _read_response(self) -> Optional[str]:
        """Read the response from the ESP8266 with a 5 second timeout."""
        if not self.serial_port or not self.serial_port.is_open:
            raise RuntimeError("Serial port not open.")

        start_time = time.time()
        response = ""
        while time.time() - start_time < self.timeout:
            try:
                line = self.serial_port.readline()
                if not line:
                    continue
                response += line.decode('utf-8', errors='ignore')
                if 'OK' in response or 'ERROR' in response or 'FAIL' in response:
                    return response
            except serial.SerialException as e:
                print(f"Serial error during response read: {e}")
                return None
        return None

    def test_connection(self) -> bool:
        """Test the connection by sending 'AT' and checking for 'OK' response."""
        if not self.serial_port or not self.serial_port.is_open:
            raise RuntimeError("Serial port not open.")

        if self._send_command("AT"):
            print("ESP8266 connection test successful.")
            return True
        else:
            print("ESP8266 connection test failed.")
            return False

    def restart(self) -> bool:
        """Restart the ESP8266 by sending 'AT+RST' and checking for 'WIFI GOT IP'."""
        if not self.serial_port or not self.serial_port.is_open:
            raise RuntimeError("Serial port not open.")

        if self._send_command("AT+RST", delay=2):
            print("ESP8266 restarted.")
            return True
        else:
            print("ESP8266 restart failed.")
            return False

    def connect_wifi(self, ssid: str, password: str) -> bool:
        """Connect to WiFi using 'AT+CWJAP_CUR' command."""
        if not self.serial_port or not self.serial_port.is_open:
            raise RuntimeError("Serial port not open.")

        command = f"AT+CWJAP_CUR=\"{ssid}\",\"{password}\""
        if self._send_command(command, delay=5):
            response = self._read_response()
            if response and "WIFI GOT IP" in response:
                print("WiFi connection successful.")
                return True
            else:
                print("WiFi connection failed.")
                return False
        else:
            print("Failed to send WiFi connect command.")
            return False

    def __enter__(self):
        """Context manager entry."""
        self.open()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        """Context manager exit."""
        self.cleanup()

