    def _read_response(self) -> Optional[str]:
        """Read the response from the ESP8266 with a 5 second timeout."""
        if not self.serial_port or not self.serial_port.is_open:
            raise RuntimeError("Serial port not open.")

        start_time = time.time()
        response = ""
        while time.time() - start_time < self.timeout:
            try:
                line = self.serial_port.readline()
                if not line:
                    continue
                response += line.decode('utf-8', errors='ignore')
                if 'OK' in response or 'ERROR' in response or 'FAIL' in response:
                    return response
            except serial.SerialException as e:
                print(f"Serial error during response read: {e}")
                return None
        return None

    def test_connection(self) -> bool:
        """Test the connection by sending 'AT' and checking for 'OK' response."""
        if not self.serial_port or not self.serial_port.is_open:
            raise RuntimeError("Serial port not open.")

        if self._send_command("AT"):
            print("ESP8266 connection test successful.")
            return True
        else:
            print("ESP8266 connection test failed.")
            return False

    def restart(self) -> bool:
        """Restart the ESP8266 by sending 'AT+RST' and checking for 'WIFI GOT IP'."""
        if not self.serial_port or not self.serial_port.is_open:
            raise RuntimeError("Serial port not open.")

        if self._send_command("AT+RST", delay=2):
            print("ESP8266 restarted.")
            return True
        else:
            print("ESP8266 restart failed.")
            return False

    def connect_wifi(self, ssid: str, password: str) -> bool:
        """Connect to WiFi using 'AT+CWJAP_CUR' command."""
        if not self.serial_port or not self.serial_port.is_open:
            raise RuntimeError("Serial port not open.")

        command = f"AT+CWJAP_CUR=\"{ssid}\",\"{password}\""
        if self._send_command(command, delay=5):
            response = self._read_response()
            if response and "WIFI GOT IP" in response:
                print("WiFi connection successful.")
                return True
            else:
                print("WiFi connection failed.")
                return False
        else:
            print("Failed to send WiFi connect command.")
            return False

    def __enter__(self):
        """Context manager entry."""
        self.open()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        """Context manager exit."""
        self.cleanup()
