        except serial.SerialException as e:
            raise RuntimeError(f"Error powering on GNSS: {e}")

    def detach(self):
        if not self.serial_port or not self.serial_port.is_open:
            raise RuntimeError("Serial port not open")
        try:
            self.serial_port.write(b'AT+CGNSPWR=0\r\n')
            response = self.serial_port.read(100).decode('utf-8')
            if 'OK' not in response:
                raise serial.SerialException("Failed to power off GNSS")
        except serial.SerialException as e:
            raise RuntimeError(f"Error powering off GNSS: {e}")

    def get_data(self):
        if not self.serial_port or not self.serial_port.is_open:
            raise RuntimeError("Serial port not open")
        try:
            data = self.serial_port.read_until(b'\r\n').decode('utf-8')
            lines = data.strip().split('\r\n')
            for line in lines:
                if line.startswith('$GPRMC'):
                    parts = line.split(',')
                    if len(parts) >= 7 and parts[2] == 'A':
