from flask import Flask, jsonify, request, abort
import serial
import time
import json
import sys
import threading
import logging

app = Flask(__name__)
app.logger.setLevel(logging.INFO)

# In-memory data store
data_store = [
    {"id": 1, "name": "Item One", "done": False},
    {"id": 2, "name": "Item Two", "done": False}
]

# Serial port configuration
SERIAL_PORT = '/dev/ttyUSB0'
SERIAL_BAUD = 9600
SERIAL_BYTESIZE = serial.EIGHTBITS
SERIAL_PARITY = serial.PARITY_NONE
SERIAL_STOPBITS = serial.STOPBITS_ONE

# Lock for thread-safe data store access
data_lock = threading.Lock()

def get_serial_connection():
    try:
        return serial.Serial(SERIAL_PORT, SERIAL_BAUD, bytesize=SERIAL_BYTESIZE,
                             parity=SERIAL_PARITY, stopbits=SERIAL_STOPBITS, timeout=1)
    except serial.SerialException as e:
        app.logger.error(f"Failed to open serial port: {e}")
        return None

@app.route('/version')
def version():
    ser = None
    try:
        ser = get_serial_connection()
        if not ser:
            return jsonify({"error": "Failed to open serial port"}), 503

        ser.write(b'*IDN?\n')
        time.sleep(0.1)
        response = ser.read(ser.in_waiting or 1024).decode('utf-8', errors='ignore')
        return jsonify({"idn": response.replace('\n', '<br>').replace('\r', '<br>')})
    except Exception as e:
        app.logger.error(f"Error reading from serial: {e}")
        return jsonify({"error": "Failed to read from serial device"}), 503
    finally:
        if ser and ser.is_open:
            ser.close()

@app.route('/getdata')
def getdata():
    with data_lock:
        return jsonify(data_store)

@app.route('/getset/<int:item_id>')
def getset(item_id):
    with data_lock:
        for item in data_store:
            if item['id'] == item_id:
                return jsonify(item)
        return jsonify({"error": "Item not found"}), 404

@app.route('/getpost/<int:item_id>/<name>')
def getpost(item_id, name):
    with data_lock:
        new_item = {
            "id": item_id,
            "name": name,
            "done": False
        }
        data_store.append(new_item)
        return jsonify(data_store)

@app.route('/postjson', methods=['GET'])
def postjson_get():
    with data_lock:
        return jsonify(data_store)

@app.route('/postjson', methods=['POST'])
def postjson_post():
    try:
        data = request.get_json() or request.form.to_dict()
        name = data.get('name', '')
        if not name:
            return jsonify({"error": "Name is required"}), 400

        with data_lock:
            new_id = len(data_store) + 1
            new_item = {
                "id": new_id,
                "name": name,
                "done": False
            }
            data_store.append(new_item)
            return jsonify(data_store)
    except json.JSONDecodeError:
        return jsonify({"error": "Invalid JSON format"}), 400
    except Exception as e:
        app.logger.error(f"Error parsing input: {e}")
        return jsonify({"error": "Malformed input"}), 400

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000, debug=False)

