import serial
import time
import sys

def send_command(serial_port, command):
    try:
        # Prefix with 'X' and terminate with newline
        message = f"X{command}\n"
        serial_port.write(message.encode())
        print(f"Sent: {message.strip()}")
    except serial.SerialException as e:
        raise RuntimeError(f"Failed to send command: {e}")

def main():
    try:
        # Configure serial connection
        serial_port = serial.Serial(
            port='/dev/rfcomm4',
            baudrate=38400,
            timeout=1
        )
        print("Connected to Bluetooth device on /dev/rfcomm4")

        while True:
            try:
                user_input = input("Enter command (type 'exit' to quit): ").strip()
                if user_input.lower() == 'exit':
                    print("Exiting...")
                    break

                send_command(serial_port, user_input)
                time.sleep(0.1)  # 0.1 second delay to avoid flooding

            except KeyboardInterrupt:
                print("\nKeyboardInterrupt: Gracefully exiting...")
                break
            except RuntimeError as e:
                print(f"Error: {e}")
            except Exception as e:
                print(f"Unexpected error: {e}")

    except serial.SerialException as e:
        print(f"Failed to connect to serial port: {e}")
    finally:
        try:
            if 'serial_port' in locals() and serial_port.is_open:
                serial_port.close()
                print("Serial connection closed.")
        except Exception as e:
            print(f"Error closing serial port: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()
